window.CONTRACTOR_QUESTIONS_LAW=[{id:"law-001",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"\xBFQu\xE9 agencia del estado de California regula y emite las licencias de contratista?",options:{a:"Department of Consumer Affairs directamente, sin sub-boards",b:"Contractors State License Board, bajo Consumer Affairs",c:"Department of Industrial Relations, Divisi\xF3n de Licencias",d:"Cal/OSHA en conjunto con el Labor Commissioner"},correct:"b",explanation:"El Contractors State License Board (CSLB) es la agencia dentro del Department of Consumer Affairs que regula y licencia a los contratistas en California. Administra examenes, investiga quejas y aplica sanciones.",reference:"B&P Code \xA77000.5"},{id:"law-002",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"\xBFCu\xE1l es el monto m\xEDnimo de un trabajo (mano de obra + materiales) para el cual se requiere licencia de contratista en California?",options:{a:"$200 o m\xE1s, bajo la antigua exenci\xF3n de handyman",b:"$300 o m\xE1s, incluyendo labor pero no materiales",c:"$500 o m\xE1s, combinando labor y materiales",d:"$1,000 o m\xE1s, salvo reparaciones urgentes"},correct:"c",explanation:"Cualquier trabajo de construcci\xF3n con valor combinado de mano de obra y materiales de $500 o m\xE1s requiere que el contratista tenga licencia CSLB. Trabajos menores califican como 'handyman' y estan exentos.",reference:"B&P Code \xA77048"},{id:"law-003",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"\xBFQu\xE9 clasificacion de licencia corresponde a un contratista de aire acondicionado y calefaccion?",options:{a:"C-10 Electrical Contractor, incluye control HVAC",b:"C-20 Warm-Air Heating, Ventilating & A/C",c:"C-36 Plumbing, por las l\xEDneas de refrigerante",d:"C-38 Refrigeration, residencial y comercial"},correct:"b",explanation:"La clasificacion C-20 (Warm-Air Heating, Ventilating and Air-Conditioning) es la licencia para contratistas de HVAC en California. La C-38 es refrigeracion, C-10 electrico y C-36 plomeria.",reference:"CCR Title 16 \xA7832.20"},{id:"law-004",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFCuantos a\xF1os de experiencia verificable se requieren para aplicar a una licencia de contratista en California?",options:{a:"2 a\xF1os de journeyman en los \xFAltimos 5 a\xF1os",b:"4 a\xF1os de experiencia en los \xFAltimos 10 a\xF1os",c:"5 a\xF1os como foreman en los \xFAltimos 7 a\xF1os",d:"6 a\xF1os combinando trade y supervisi\xF3n, en 8"},correct:"b",explanation:"CSLB requiere 4 a\xF1os de experiencia a nivel journeyman, foreman, supervisor o contratista en los \xFAltimos 10 a\xF1os antes de la aplicacion. La experiencia debe ser verificada por alguien calificado.",reference:"B&P Code \xA77068"},{id:"law-005",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"\xBFCada cuanto tiempo debe renovarse una licencia de contratista en California?",options:{a:"Anualmente, junto con el seller's permit",b:"Cada dos a\xF1os, antes de la fecha de expiracion",c:"Cada tres a\xF1os, via renewal activo o inactivo",d:"Cada cinco a\xF1os, salvo disciplina previa"},correct:"b",explanation:"Las licencias de contratista en California son vigentes por dos a\xF1os y deben renovarse antes de su expiracion. Si expira, hay un periodo de gracia pero con fee adicional.",reference:"B&P Code \xA77140"},{id:"law-006",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"Un Responsible Managing Officer (RMO) o Responsible Managing Employee (RME) debe trabajar cuantas horas m\xEDnimas al mes en la empresa?",options:{a:"20 horas por semana, con registro de timesheet",b:"32 horas por semana u 80% del tiempo operacional",c:"40 horas fijas por semana, sin excepcion",d:"Sin m\xEDnimo obligatorio, solo supervisi\xF3n general"},correct:"b",explanation:"El RMO/RME debe estar activamente involucrado al menos 32 horas por semana o 80% del tiempo operacional del negocio, lo que sea menos. No se permite 'prestar' la licencia sin participacion real.",reference:"B&P Code \xA77068.1"},{id:"law-007",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFCual es la consecuencia de actuar como contratista sin licencia en California por primera vez?",options:{a:"Advertencia verbal y carta de cese de CSLB",b:"Misdemeanor: hasta 6 meses c\xE1rcel y $5,000 multa",c:"Felony autom\xE1tico con registro permanente",d:"Multa civil fija de $250, sin antecedente penal"},correct:"b",explanation:"Contratar sin licencia es un misdemeanor penalizado con hasta 6 meses de c\xE1rcel y/o multa hasta $5,000. En reincidencia las penas aumentan y puede ser felony en situaciones de desastre declarado.",reference:"B&P Code \xA77028"},{id:"law-008",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"hard",question:"\xBFQu\xE9 tipo de estructura de negocio permite a los due\xF1os protegerse de responsabilidad personal pero con 'pass-through' taxation?",options:{a:"Sole Proprietorship con DBA registrado en condado",b:"General Partnership con acuerdo escrito y EIN",c:"LLC (Limited Liability Company) con CSLB bond",d:"C-Corporation con eleccion Subchapter S vigente"},correct:"c",explanation:"La LLC combina proteccion de responsabilidad limitada con pass-through taxation (las ganancias pasan directo al 1040 personal sin doble impuesto corporativo). Requiere CSLB bond adicional de LLC de $100,000.",reference:"B&P Code \xA77071.6.5"},{id:"law-009",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFCual es el bond adicional requerido para una LLC con licencia CSLB (sobre el contractor's bond)?",options:{a:"$25,000, igual al contractor's bond est\xE1ndar",b:"$50,000, monto hist\xF3rico pre-2017 para LLCs",c:"$75,000, aplicable solo a LLCs out-of-state",d:"$100,000, espec\xEDfico para wages y benefits"},correct:"d",explanation:"Las LLCs con licencia CSLB deben postear un bond adicional de $100,000 espec\xEDficamente para proteger wages y benefits de empleados. Esto es ADEM\xC1S del contractor's bond de $25,000.",reference:"B&P Code \xA77071.6.5"},{id:"law-010",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"Si cambias la entidad de tu negocio (ej. sole prop a corporation), \xBFpuedes transferir tu licencia CSLB existente?",options:{a:"S\xED, automaticamente al actualizar Secretary of State",b:"S\xED, pagando fee de transferencia y nuevo bond",c:"No, la licencia no es transferible entre entidades",d:"Solo con aviso escrito a CSLB 30 d\xEDas antes"},correct:"c",explanation:"Las licencias CSLB NO son transferibles entre entidades distintas. Al cambiar de sole prop a corporation o LLC debes aplicar nueva licencia para la nueva entidad, aunque puede haber process simplificado.",reference:"B&P Code \xA77075.1"},{id:"law-011",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFQu\xE9 debe hacer un contratista si cambia de direccion comercial o telefono?",options:{a:"Nada, CSLB actualiza v\xEDa Secretary of State",b:"Notificar a CSLB por escrito dentro de 90 d\xEDas",c:"Esperar al ciclo de renovaci\xF3n de la licencia",d:"Publicar aviso en peri\xF3dico local del condado"},correct:"b",explanation:"Todos los cambios de direccion, nombre comercial, telefono o personal (RMO/RME, oficiales) deben reportarse por escrito a CSLB dentro de 90 d\xEDas. No hacerlo puede resultar en disciplina administrativa.",reference:"B&P Code \xA77083"},{id:"law-012",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"\xBFCu\xE1l es la clasificacion de licencia 'A' en California?",options:{a:"General Building Contractor, structuras con 2+ trades",b:"General Engineering Contractor, obras de ingenier\xEDa",c:"Specialty Contractor en un solo trade autorizado",d:"Residential Remodeler, solo vivienda unifamiliar"},correct:"b",explanation:"La Class A es General Engineering Contractor \u2014 obras que requieren conocimiento especializado de ingenieria (carreteras, puentes, excavaciones mayores). Class B es General Building y Class C son especialidades.",reference:"B&P Code \xA77056"},{id:"law-013",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"\xBFCu\xE1l es la clasificacion 'B' de CSLB?",options:{a:"General Engineering Contractor, obras civiles",b:"General Building Contractor, estructuras 2+ trades",c:"Electrical Specialty Contractor (Class C-10)",d:"HVAC Specialty Contractor (Class C-20)"},correct:"b",explanation:"La Class B es General Building Contractor \u2014 trabaja con structuras que usan al menos dos trades distintos. Requiere uso de m\xFAltiples oficios en un mismo proyecto para justificar su uso.",reference:"B&P Code \xA77057"},{id:"law-014",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"hard",question:"\xBFPuede un contratista Class B hacer un trabajo que consiste \xDANICAMENTE de framing o carpinter\xEDa sin otros trades?",options:{a:"S\xED, sin limitaciones de scope o monto",b:"Solo si el contrato total es menor a $500",c:"No, requiere 2+ trades o licencia C-5 Framing",d:"S\xED, \xFAnicamente en obra residencial nueva"},correct:"c",explanation:"Un Class B requiere que el proyecto involucre al menos dos trades no relacionados. Un solo trade (solo framing, solo drywall) requiere la clasificacion specialty correspondiente, como C-5 Framing.",reference:"B&P Code \xA77057"},{id:"law-015",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFCuantas clasificaciones specialty 'C' existen actualmente en California?",options:{a:"Aproximadamente 20, una por cada trade principal",b:"Aproximadamente 30, tras consolidaci\xF3n de 2015",c:"Aproximadamente 40+, cubriendo todos los trades",d:"Solamente 10, los trades m\xE1s comunes en CA"},correct:"c",explanation:"California tiene aproximadamente 40+ clasificaciones specialty (Class C), cada una cubriendo un trade especifico como C-10 electrico, C-20 HVAC, C-36 plomeria, C-38 refrigeracion, C-39 roofing, etc.",reference:"CCR Title 16 \xA7832"},{id:"law-016",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFQue significa 'home improvement contract' bajo la ley de California?",options:{a:"Cualquier trabajo residencial independientemente del monto",b:"Contrato >$500 para mejoras a residencia existente",c:"Solo construccion nueva residencial, no remodelacion",d:"Trabajos comerciales o industriales bajo $10,000"},correct:"b",explanation:"Home Improvement Contract es cualquier contrato mayor a $500 para alterar, reparar, agregar o mejorar una residencia existente del propietario. Debe cumplir con requisitos espec\xEDficos del B&P Code \xA77159.",reference:"B&P Code \xA77151"},{id:"law-017",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFQu\xE9 tipo de licencia necesita un vendedor que ofrece home improvement puerta a puerta?",options:{a:"Ninguna, si trabaja por comisi\xF3n y no firma",b:"Solo la licencia CSLB del contratista que representa",c:"Home Improvement Salesperson (HIS) ante CSLB",d:"Licencia de Real Estate Salesperson bajo DRE"},correct:"c",explanation:"Cualquier vendedor que negocia home improvement contracts debe estar registrado como Home Improvement Salesperson (HIS) con CSLB. Esto incluye canvassers y closers que entran a casas.",reference:"B&P Code \xA77152"},{id:"law-018",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"easy",question:"Si un contratista quiere operar bajo un nombre comercial distinto al legal (DBA), \xBFqu\xE9 debe hacer?",options:{a:"Nada, puede usar el DBA libremente en marketing",b:"Registrar FBN en el condado y notificar a CSLB",c:"Publicar \xFAnicamente en peri\xF3dico local aprobado",d:"Solo pagar fee de name change directo a CSLB"},correct:"b",explanation:"Un DBA (doing business as) requiere registro de Fictitious Business Name (FBN) en el condado donde opera, publicacion en periodico, y notificacion a CSLB. La licencia se emite al nombre exacto registrado.",reference:"B&P Code \xA717900 y \xA77083"},{id:"law-019",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"hard",question:"\xBFCu\xE1l es el fee actual de aplicacion para una nueva licencia original con CSLB (aplicacion inicial)?",options:{a:"$150 non-refundable, seg\xFAn tabla anterior a 2017",b:"Aproximadamente $330, non-refundable al aplicar",c:"$600 combinando aplicacion y licencia inicial",d:"$1,200 si incluye bond y fingerprinting fees"},correct:"b",explanation:"El fee de aplicacion original (non-refundable) es aproximadamente $330, mas fee de licencia inicial al aprobar. Los fees son ajustados periodicamente por CSLB via regulacion.",reference:"CCR Title 16 \xA7811"},{id:"law-020",category:"Organizaci\xF3n de Negocios y Licencias",difficulty:"medium",question:"\xBFQu\xE9 examen debe pasar un aplicante a licencia CSLB (ademas del trade exam)?",options:{a:"Solo el trade exam especifico del oficio aplicado",b:"Law and Business exam, cubriendo B&P y Labor Code",c:"CPA exam para contabilidad de construcci\xF3n",d:"OSHA 30 como prerequisito de safety b\xE1sica"},correct:"b",explanation:"Todos los aplicantes deben pasar el Law and Business exam ademas del trade exam especifico (excepto algunas exenciones). Cubre contract law, finanzas, employment, bonds, liens y safety.",reference:"B&P Code \xA77065"},{id:"law-021",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFQu\xE9 es el 'current ratio' en contabilidad?",options:{a:"Ingresos totales divididos entre gastos operativos",b:"Activos circulantes divididos entre pasivos circulantes",c:"Deuda total a largo plazo dividida entre capital",d:"Ganancia neta dividida entre ventas totales del a\xF1o"},correct:"b",explanation:"Current ratio = activos circulantes / pasivos circulantes. Mide la capacidad de una empresa de pagar sus obligaciones a corto plazo. Un ratio de 2:1 o mayor se considera saludable.",reference:"GAAP / Accounting Principles"},{id:"law-022",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFQu\xE9 representa la ecuacion fundamental de contabilidad?",options:{a:"Ingresos = Gastos + Ganancia del periodo contable",b:"Activos = Pasivos + Capital (Assets = Liabilities + Equity)",c:"Debitos totales = Cr\xE9ditos totales del libro diario",d:"Cash flow operativo = Net income + Depreciation anual"},correct:"b",explanation:"La ecuacion fundamental es Activos = Pasivos + Capital (Assets = Liabilities + Equity). Este balance siempre debe cumplirse en el Balance Sheet y es base de la contabilidad double-entry.",reference:"GAAP / Accounting Principles"},{id:"law-023",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 metodo contable es mas com\xFAn para contratistas peque\xF1os?",options:{a:"Accrual method, requerido para GAAP completo",b:"Cash method, reconoce ingreso al cobrar el cheque",c:"Percentage of completion, requerido para contratos largos",d:"Completed contract, difiere ingreso hasta entrega final"},correct:"b",explanation:"El cash method reconoce ingresos cuando se reciben y gastos cuando se pagan. Es el mas simple y permitido por IRS para contratistas con ingresos bajo cierto umbral (actualmente $29M+ aprox 2024).",reference:"IRS Publication 334"},{id:"law-024",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es el 'percentage of completion' en contabilidad de construccion?",options:{a:"Porcentaje del payroll sobre ingresos totales del a\xF1o",b:"M\xE9todo que reconoce ingresos seg\xFAn avance del proyecto",c:"Porcentaje de ganancia bruta requerido por el IRS",d:"C\xE1lculo del break-even point usando costos fijos"},correct:"b",explanation:"Percentage of Completion reconoce ingresos y gastos proporcionalmente al avance del proyecto (% de costos incurridos / costos totales estimados). Requerido para contratos largos en empresas grandes.",reference:"ASC 606 / IRS \xA7460"},{id:"law-025",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFQu\xE9 documento fiscal se entrega a un subcontratista independiente (no empleado) que recibio $600 o m\xE1s en el a\xF1o?",options:{a:"W-2 Wage and Tax Statement, como empleado",b:"1099-NEC, Nonemployee Compensation anual",c:"W-4 Employee's Withholding Certificate federal",d:"I-9 Employment Eligibility Verification USCIS"},correct:"b",explanation:"El 1099-NEC (Nonemployee Compensation) se emite a contratistas independientes que recibieron $600 o m\xE1s durante el a\xF1o fiscal. Reemplazo al 1099-MISC para esta funcion a partir de 2020.",reference:"IRS Form 1099-NEC instructions"},{id:"law-026",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFQu\xE9 formulario debe llenar un subcontratista para proporcionar su TIN antes de recibir pago?",options:{a:"W-2, emitido al final del a\xF1o fiscal vigente",b:"W-4 para indicar allowances de retenci\xF3n federal",c:"W-9, Request for Taxpayer Identification Number",d:"I-9 de verificaci\xF3n de elegibilidad migratoria"},correct:"c",explanation:"El W-9 (Request for Taxpayer Identification Number) lo llena el subcontratista o vendor para dar su SSN/EIN al pagador. Es requerido antes de emitir 1099s al final del a\xF1o.",reference:"IRS Form W-9"},{id:"law-027",category:"Finanzas y Contabilidad",difficulty:"medium",question:"Si un contratista no obtiene un W-9 de un subcontratista, \xBFqu\xE9 debe hacer?",options:{a:"Pagar el invoice completo y reportarlo al IRS",b:"Retener 24% de backup withholding y remitir al IRS",c:"Negarse a pagar hasta que entregue formulario W-9",d:"Reportar al sub a CSLB por falta de cooperaci\xF3n"},correct:"b",explanation:"Si el pagador no tiene un W-9 valido, debe aplicar backup withholding de 24% (actualmente) y remitirlo al IRS. Es proteccion para el pagador contra responsabilidad por impuestos no pagados.",reference:"IRS \xA73406"},{id:"law-028",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es 'overhead' en un negocio de contratista?",options:{a:"Costos directos de labor y materiales del proyecto",b:"Gastos indirectos fijos: renta, seguros, oficina",c:"Margen de utilidad esperado sobre costos directos",d:"Cost of goods sold espec\xEDfico de cada proyecto"},correct:"b",explanation:"Overhead son los gastos indirectos necesarios para operar el negocio pero no atribuibles directamente a un solo proyecto (renta, seguros, telefono, admin, marketing). Debe incluirse en bids como porcentaje.",reference:"Construction Accounting Principles"},{id:"law-029",category:"Finanzas y Contabilidad",difficulty:"hard",question:"Si tus costos directos son $50,000 y tu overhead anual es 20%, \xBFcu\xE1nto debes cobrar para breakeven (sin utilidad)?",options:{a:"$50,000, cubre costos directos sin overhead aplicado",b:"$55,000, suma 10% a costos directos como default",c:"$60,000, agrega 20% directo sobre costos del proyecto",d:"$62,500, f\xF3rmula costos / (1 - overhead%) correcta"},correct:"d",explanation:"Para breakeven con 20% overhead: precio = costos / (1 - overhead%) = $50,000 / 0.80 = $62,500. No es simplemente sumar 20% ($60,000) porque necesitas recuperar overhead del precio final.",reference:"Construction Estimating"},{id:"law-030",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es 'cash flow' y por qu\xE9 es cr\xEDtico para contratistas?",options:{a:"La ganancia neta anual reportada en el Form 1040",b:"Movimiento real de dinero entrante y saliente diario",c:"Total de ventas antes de costos directos e indirectos",d:"Inventario de materiales almacenados en bodega"},correct:"b",explanation:"Cash flow es el movimiento real de dinero in/out del negocio. Un contratista puede ser rentable en papel pero quebrar por cash flow negativo si los clientes pagan tarde mientras gastos (payroll, materiales) siguen.",reference:"Construction Financial Management"},{id:"law-031",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFCu\xE1ntos a\xF1os debe guardar un contratista sus registros fiscales segun el IRS generalmente?",options:{a:"1 a\xF1o, salvo si hay auditor\xEDa pendiente abierta",b:"3 a\xF1os, m\xEDnimo estatutario de IRS por default",c:"7 a\xF1os recomendados, cubre bad debt y auditor\xEDas",d:"10 a\xF1os, requerido solo para payroll records EDD"},correct:"c",explanation:"IRS generalmente requiere 3 a\xF1os, pero 7 a\xF1os es la recomendacion est\xE1ndar para cubrir situaciones de auditoria, bad debt deductions y underreported income. Algunos registros (property, payroll) mas.",reference:"IRS Publication 583"},{id:"law-032",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es 'depreciation' en el contexto de equipo de construccion?",options:{a:"P\xE9rdida por robo o casualty reportada en Form 4684",b:"Asignaci\xF3n del costo del activo durante vida \xFAtil",c:"Descuento del vendedor al momento de la compra",d:"Costo de mantenimiento preventivo anual registrado"},correct:"b",explanation:"Depreciation es la asignacion sistem\xE1tica del costo de un activo (equipo, vehiculos) durante su vida \xFAtil como gasto deducible. Metodos incluyen straight-line, MACRS, Section 179, bonus depreciation.",reference:"IRS Publication 946"},{id:"law-033",category:"Finanzas y Contabilidad",difficulty:"hard",question:"\xBFQue permite Section 179 del IRS para equipo de contratista?",options:{a:"Exenci\xF3n total de sales tax en compras de equipo",b:"Deducci\xF3n inmediata del costo total en a\xF1o de compra",c:"Cr\xE9dito fiscal del 10% sobre equipo nuevo adquirido",d:"Depreciaci\xF3n MACRS acelerada al 50% en a\xF1o uno"},correct:"b",explanation:"Section 179 permite deducir inmediatamente el costo total de equipo comercial cualificado (hasta ~$1.16M en 2023) en el a\xF1o de compra, en vez de depreciarlo durante a\xF1os. \xDAtil para ahorro fiscal inmediato.",reference:"IRC \xA7179"},{id:"law-034",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFQu\xE9 es el Income Statement (P&L)?",options:{a:"Lista de activos, pasivos y capital a fecha de corte",b:"Reporte de ingresos, gastos y resultado en un periodo",c:"Registro diario de cash in y cash out por cuenta",d:"Detalle de cambios en equity durante a\xF1o fiscal"},correct:"b",explanation:"El Income Statement (Profit & Loss / P&L) reporta ingresos, costos, gastos y la ganancia o p\xE9rdida neta durante un periodo espec\xEDfico (mes, trimestre, a\xF1o). Muestra rentabilidad del negocio.",reference:"GAAP / FASB"},{id:"law-035",category:"Finanzas y Contabilidad",difficulty:"easy",question:"\xBFQu\xE9 es el Balance Sheet?",options:{a:"Reporte anual de ingresos y gastos acumulados",b:"Fotograf\xEDa de activos, pasivos y equity a una fecha",c:"Lista detallada de cuentas por cobrar actuales",d:"Proyecci\xF3n de ventas y cash flow para 12 meses"},correct:"b",explanation:"El Balance Sheet es una fotograf\xEDa de la posicion financiera en un momento espec\xEDfico: activos = pasivos + equity. Incluye current y long-term assets/liabilities. Requerido para prestamos y bonding.",reference:"GAAP / FASB"},{id:"law-036",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es 'working capital'?",options:{a:"Dinero reservado exclusivamente para comprar equipo",b:"Activos circulantes menos pasivos circulantes netos",c:"Capital prestado del banco a tasa variable actual",d:"Ganancia reinvertida del a\xF1o fiscal previo cerrado"},correct:"b",explanation:"Working capital = activos circulantes - pasivos circulantes. Representa el capital disponible para operaciones diarias. Critical para contratistas que necesitan financiar materiales y payroll antes de cobrar.",reference:"Construction Financial Management"},{id:"law-037",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es 'accounts receivable' (AR)?",options:{a:"Dinero que el negocio debe a proveedores o subs",b:"Dinero que los clientes deben al negocio por trabajo",c:"Inventario de materiales almacenados en bodega",d:"Gastos pre-pagados, como seguros y renta adelantada"},correct:"b",explanation:"Accounts Receivable son cantidades que los clientes te deben por servicios/materiales ya provistos pero no pagados. Es un activo circulante. AR envejecido (90+ d\xEDas) indica problemas de cobro.",reference:"GAAP"},{id:"law-038",category:"Finanzas y Contabilidad",difficulty:"medium",question:"\xBFQu\xE9 es 'accounts payable' (AP)?",options:{a:"Cantidades que clientes del negocio a\xFAn adeudan",b:"Dinero que el negocio debe a proveedores y subs",c:"Impuestos payroll pendientes de remisi\xF3n al EDD",d:"N\xF3mina devengada pero no pagada a\xFAn a empleados"},correct:"b",explanation:"Accounts Payable son cantidades que tu negocio debe a proveedores, subcontratistas y vendors por bienes/servicios ya recibidos. Es un pasivo circulante. Manejarlo bien preserva cash flow.",reference:"GAAP"},{id:"law-039",category:"Finanzas y Contabilidad",difficulty:"hard",question:"Si tu ganancia bruta (gross profit) es 30% y overhead es 20%, \xBFcual es tu ganancia neta?",options:{a:"50%, sumando gross profit m\xE1s overhead absorbido",b:"10%, restando overhead de gross profit del periodo",c:"6%, multiplicando 30% por 20% como margen combinado",d:"No puede determinarse sin ingresos totales del a\xF1o"},correct:"b",explanation:"Ganancia neta = gross profit - overhead = 30% - 20% = 10%. Gross profit cubre overhead; lo que sobra es net profit. Un contratista sano busca 8-15% de net profit despu\xE9s de todos los gastos.",reference:"Construction Financial Management"},{id:"law-040",category:"Finanzas y Contabilidad",difficulty:"medium",question:"Si un cliente no paga un invoice despu\xE9s de 90 d\xEDas, \xBFqu\xE9 accion tiene mayor prioridad?",options:{a:"Demandar inmediatamente en small claims court",b:"Preservar derechos de lien: preliminary y mechanic's",c:"Llamar a CSLB y presentar queja formal escrita",d:"Ofrecer descuento del 50% para cierre r\xE1pido"},correct:"b",explanation:"Antes de demandar, preserva derechos via preliminary notice (ya debe estar hecho dentro de 20 d\xEDas del primer trabajo) y filing mechanic's lien (dentro de 90 d\xEDas de completion). Son tus garantias mas fuertes.",reference:"Civil Code \xA78400 et seq."},{id:"law-041",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFCu\xE1ndo se requiere workers' compensation insurance en California?",options:{a:"Solo con 5 o m\xE1s empleados tiempo completo",b:"Con cualquier empleado, incluyendo uno solo",c:"Solo para contratistas de construcci\xF3n pesada",d:"Solo cuando ventas anuales superan $1 mill\xF3n"},correct:"b",explanation:"California requiere workers' comp con UN solo empleado. Para contratistas con licencia CSLB, es REQUERIDO tener workers' comp o una exemption valida, sin importar numero de empleados desde 2011 para C-39 roofers y en general para todos.",reference:"Labor Code \xA73700 / B&P Code \xA77125"},{id:"law-042",category:"Empleo y Payroll",difficulty:"medium",question:"Como contratista C-39 (roofing), \xBFpuedes operar sin workers' comp aunque no tengas empleados?",options:{a:"S\xED, igual que cualquier otro sole proprietor",b:"No, C-39 requiere workers' comp siempre desde 2011",c:"Solo si se postea bond adicional de $100,000",d:"S\xED, pero con seguro de accidentes de $500,000"},correct:"b",explanation:"Desde 2011, C-39 roofers DEBEN mantener workers' comp aun sin empleados, dada la alta peligrosidad. Esta es una excepcion unica a la regla general que permite exempciones a sole props sin empleados.",reference:"B&P Code \xA77125(c)"},{id:"law-043",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFQu\xE9 formulario federal verifica elegibilidad para trabajar en USA?",options:{a:"W-4, para retenciones federales del empleado",b:"W-9, para subcontratistas independientes 1099",c:"I-9, Employment Eligibility Verification USCIS",d:"1099-NEC, reportando pagos al non-employee"},correct:"c",explanation:"El Form I-9 (Employment Eligibility Verification) debe completarse para cada nuevo empleado dentro de 3 d\xEDas de comenzar, verificando identidad y autorizacion de trabajo en USA. Mantener en archivo.",reference:"USCIS Form I-9 / IRCA"},{id:"law-044",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFQu\xE9 formulario llena un empleado para determinar retenciones federales?",options:{a:"I-9, verifica identidad y autorizaci\xF3n de trabajo",b:"W-2, emitido al empleado al cierre de cada a\xF1o",c:"W-4, Employee's Withholding Certificate federal",d:"W-9, aplica solo a contractors independientes"},correct:"c",explanation:"El W-4 (Employee's Withholding Certificate) lo llena el empleado para indicar cuanto federal income tax retener de su cheque. Debe mantenerse actualizado si cambian circunstancias (dependientes, etc).",reference:"IRS Form W-4"},{id:"law-045",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFQu\xE9 formulario estatal de California es equivalente al W-4 para retenciones estatales?",options:{a:"DE-4, Employee's Withholding Allowance Certificate",b:"DE-34, New Employee Report al EDD en 20 d\xEDas",c:"DE-6, Quarterly Wage and Withholding Report",d:"DE-9, Quarterly Contribution Return empleador"},correct:"a",explanation:"El DE-4 (Employee's Withholding Allowance Certificate) es el equivalente California del W-4, usado para determinar retenciones de CA state income tax. Puede diferir del W-4 federal.",reference:"EDD DE-4"},{id:"law-046",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFDentro de cuantos dias debe reportarse un nuevo empleado al estado de California?",options:{a:"10 d\xEDas via formulario DE-34 al EDD",b:"15 d\xEDas, plazo anterior a reforma de 1998",c:"20 d\xEDas desde fecha de contrataci\xF3n inicial",d:"30 d\xEDas, alineado con IRS federal default"},correct:"c",explanation:"Debes reportar new hires via EDD form DE-34 dentro de 20 d\xEDas de la fecha de contratacion. Ayuda al estado a colectar child support, y no hacerlo tiene penalizacion.",reference:"UI Code \xA71088.5 / EDD DE-34"},{id:"law-047",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFCu\xE1l es el minimum wage estatal de California en 2024?",options:{a:"$13.00/hora, vigente hasta finales de 2021",b:"$15.50/hora, vigente durante el a\xF1o 2023 en CA",c:"$16.00/hora, vigente para todo empleador en 2024",d:"$18.00/hora, aplicable solo en LA y SF \xFAnicamente"},correct:"c",explanation:"El minimum wage estatal de California es $16.00/hora en 2024. Algunas ciudades (LA, SF, Oakland, San Jose) tienen minimum wages locales m\xE1s altos que deben respetarse.",reference:"Labor Code \xA71182.12"},{id:"law-048",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFQu\xE9 test usa California para determinar si un trabajador es independent contractor vs empleado?",options:{a:"IRS 20-factor test, abandonado por CA en 2019",b:"ABC Test, codificado por AB 5 bajo \xA72775",c:"Economic reality test del FLSA federal",d:"Right to control test del common law cl\xE1sico"},correct:"b",explanation:"Desde AB 5 (2019), California usa el ABC Test: el trabajador se presume empleado a menos que A) est\xE9 libre de control, B) haga trabajo fuera del curso normal del negocio, y C) est\xE9 engaged en negocio independiente.",reference:"Labor Code \xA72775 (AB 5)"},{id:"law-049",category:"Empleo y Payroll",difficulty:"hard",question:"Bajo el ABC Test, \xBFqu\xE9 condicion es MAS DIFICIL de cumplir para contratistas que 'hacen pasar' empleados como 1099?",options:{a:"Parte A, ausencia de control y direcci\xF3n directa",b:"Parte B, trabajo fuera del curso normal del negocio",c:"Parte C, existencia de negocio independiente propio",d:"Todas las partes son f\xE1ciles de cumplir si son 1099"},correct:"b",explanation:"La Parte B es la mas dificil: el trabajo debe estar fuera del curso usual del negocio. Un contratista HVAC que contrata a un t\xE9cnico HVAC como 1099 casi siempre falla la Parte B (el tecnico hace exactamente lo que hace el negocio).",reference:"Labor Code \xA72775"},{id:"law-050",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFCu\xE1ndo debe pagarse overtime en California a empleados no-exentos?",options:{a:"Solo despu\xE9s de completar 40 horas en la semana",b:"Despu\xE9s de 8 horas al d\xEDa o 40 a la semana; doble a 12",c:"\xDAnicamente en trabajo realizado d\xEDas feriados federales",d:"Cuando el empleado lo solicita expresamente por escrito"},correct:"b",explanation:"California exige overtime (1.5x) despu\xE9s de 8 horas en un d\xEDa o 40 horas a la semana, y doble tiempo despu\xE9s de 12 horas en un d\xEDa. Tambi\xE9n el s\xE9ptimo d\xEDa consecutivo tiene reglas especiales.",reference:"Labor Code \xA7510"},{id:"law-051",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFCuando aplica 'double time' en California?",options:{a:"Nunca, solo existe overtime 1.5x bajo CA law",b:"Tras 12 horas diarias, o 8h en 7mo d\xEDa consecutivo",c:"Los domingos, independientemente de las horas totales",d:"\xDAnicamente en feriados federales oficiales del a\xF1o"},correct:"b",explanation:"Double time (2x regular rate) aplica: 1) despu\xE9s de 12 horas en un d\xEDa laboral, 2) despu\xE9s de 8 horas en el 7mo d\xEDa consecutivo de trabajo en una semana. California es de las m\xE1s estrictas en overtime.",reference:"Labor Code \xA7510"},{id:"law-052",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFCon qu\xE9 frecuencia m\xEDnima deben pagarse los empleados en California?",options:{a:"Mensual, solo para empleados exentos administrativos",b:"Semi-monthly (dos veces al mes) como m\xEDnimo default",c:"Trimestralmente, alineado con DE-9 de EDD CA",d:"Al terminar el proyecto o job espec\xEDfico asignado"},correct:"b",explanation:"California requiere pay periods semi-monthly (dos veces al mes) como minimo para la mayoria de empleados. Payroll debe pagarse dentro de ciertos dias despu\xE9s del fin del periodo. Weekly/bi-weekly tambi\xE9n aceptable.",reference:"Labor Code \xA7204"},{id:"law-053",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFCu\xE1ndo debe entregarse el \xFAltimo cheque a un empleado despedido (fired/terminated)?",options:{a:"Al siguiente payday regular del calendario payroll",b:"Dentro de 72 horas desde el aviso de terminaci\xF3n",c:"Inmediatamente, al momento mismo de la terminaci\xF3n",d:"Dentro de 30 d\xEDas calendario desde ultimo d\xEDa trabajo"},correct:"c",explanation:"Si despides a un empleado, debes entregar todas las wages adeudadas INMEDIATAMENTE al momento de terminacion. No hacerlo incurre en waiting time penalties (hasta 30 d\xEDas de salario).",reference:"Labor Code \xA7201"},{id:"law-054",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFCu\xE1ndo debe entregarse el \xFAltimo cheque a un empleado que renuncia sin aviso?",options:{a:"Inmediatamente, en el \xFAltimo d\xEDa trabajado efectivo",b:"Dentro de 72 horas a partir del d\xEDa de la renuncia",c:"Al siguiente payday regular de la empresa programado",d:"Dentro de 30 d\xEDas, estilo federal FLSA por default"},correct:"b",explanation:"Si un empleado renuncia SIN aviso, tienes 72 horas para pagar todas las wages finales. Si renuncia CON al menos 72 horas de aviso, debes pagar el \xFAltimo d\xEDa de trabajo.",reference:"Labor Code \xA7202"},{id:"law-055",category:"Empleo y Payroll",difficulty:"hard",question:"\xBFCu\xE1l es la waiting time penalty por no pagar wages finales a tiempo?",options:{a:"Multa fija de $500 por empleado no pagado a tiempo",b:"Salario diario continuo del empleado hasta 30 d\xEDas",c:"10% del salario total adeudado, por cada d\xEDa tarde",d:"No existe penalty autom\xE1tica si hay disputa leg\xEDtima"},correct:"b",explanation:"La waiting time penalty es el salario diario del empleado continuando por cada d\xEDa tarde, hasta por 30 d\xEDas calendario. Puede sumar miles de d\xF3lares por un solo empleado. Motivacion fuerte para pagar a tiempo.",reference:"Labor Code \xA7203"},{id:"law-056",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFQu\xE9 impuesto paga el EMPLEADOR basado en nomina en California (ademas del federal)?",options:{a:"Solo federal income tax retenido del empleado",b:"SUI (Unemployment) y ETT (Training Tax) estatal",c:"\xDAnicamente CA sales tax en bienes vendidos",d:"Property tax anual sobre n\xF3mina acumulada"},correct:"b",explanation:"Empleadores en CA pagan SUI (unemployment, variable rate), ETT (0.1% primeros $7,000/empleado), ademas de federal FUTA. Los empleados pagan SDI (disability) y PIT (state income tax) via retencion.",reference:"UI Code \xA7976 et seq. / EDD"},{id:"law-057",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFQu\xE9 se retiene del cheque del empleado en California (no del empleador)?",options:{a:"Federal income, SS, Medicare, CA SDI y CA PIT",b:"Solo federal income tax y FICA combinado b\xE1sico",c:"\xDAnicamente State Disability Insurance (CA SDI)",d:"Workers' comp premium proporcional semanal del sueldo"},correct:"a",explanation:"Retenciones del empleado: Federal Income Tax, Social Security (6.2%), Medicare (1.45%), CA State Disability Insurance (SDI), y CA Personal Income Tax (PIT). Workers comp NO se deduce del empleado.",reference:"IRS / EDD / FICA"},{id:"law-058",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFCual es el porcentaje de Social Security que paga el empleado?",options:{a:"1.45%, porci\xF3n Medicare sin l\xEDmite aplicable",b:"6.2%, hasta el wage base cap anual definido",c:"7.65%, FICA combinado de SS m\xE1s Medicare",d:"12.4%, tasa combinada empleado m\xE1s empleador"},correct:"b",explanation:"Social Security es 6.2% del empleado hasta el wage base ($168,600 en 2024). El empleador iguala con otro 6.2%. Total FICA con Medicare es 7.65% por lado (15.3% total split).",reference:"IRC \xA73101 / \xA73111"},{id:"law-059",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFCual es el porcentaje Medicare que paga el empleado?",options:{a:"1.45% m\xE1s 0.9% adicional sobre $200,000 anuales",b:"6.2%, tope en el wage base m\xE1ximo del a\xF1o vigente",c:"7.65%, FICA combinado con Social Security uniforme",d:"2.9%, Medicare total combinado ambos lados split"},correct:"a",explanation:"Medicare es 1.45% del empleado sin tope, m\xE1s 0.9% adicional sobre $200,000 de earnings (single). El empleador iguala 1.45% (sin adicional). Total combined Medicare es 2.9% base.",reference:"IRC \xA73101(b)"},{id:"law-060",category:"Empleo y Payroll",difficulty:"hard",question:"Si clasificas incorrectamente a un empleado como 1099 contractor en California, \xBFcu\xE1l es la sancion por worker (bajo Labor Code \xA7226.8)?",options:{a:"$100 por infracci\xF3n, monto hist\xF3rico antes de 2011",b:"$5,000-$15,000 por violaci\xF3n; hasta $25,000 si patr\xF3n",c:"Solo pagar impuestos atrasados y back wages simples",d:"Warning por CSLB sin penalty monetario espec\xEDfico"},correct:"b",explanation:"Misclassification willful tiene penalties civiles de $5,000-$15,000 por violacion, $10,000-$25,000 si hay patron. Esto es ADEM\xC1S de back wages, overtime, impuestos, y posible disciplina CSLB.",reference:"Labor Code \xA7226.8"},{id:"law-061",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFQu\xE9 son las 'meal breaks' bajo ley California?",options:{a:"Opcionales si el empleado firma waiver por escrito",b:"30 min no pagados antes de 5h; segundo antes de 10h",c:"15 minutos pagados cada 4 horas trabajadas continuas",d:"1 hora pagada al d\xEDa para empleados no-exentos fijos"},correct:"b",explanation:"California requiere meal break de 30 min (unpaid, uninterrupted) antes de completar 5 horas. Segundo meal antes de 10 horas. Puede waiverse bajo condiciones. Rest breaks de 10 min pagados cada 4 horas.",reference:"Labor Code \xA7512 / IWC Wage Orders"},{id:"law-062",category:"Empleo y Payroll",difficulty:"medium",question:"Si un empleador no provee meal break, \xBFqu\xE9 debe pagar?",options:{a:"Nada, siempre que el empleado haya firmado waiver",b:"1 hora adicional de premium pay al regular rate",c:"Double time completo durante todo el d\xEDa trabajado",d:"Penalty fija de $100 por infracci\xF3n tipo wage order"},correct:"b",explanation:"Por cada d\xEDa que no se provea meal break o rest break adecuado, el empleador debe pagar 1 hora adicional al regular rate como 'premium pay' (meal/rest break premium). Separada por cada tipo de break.",reference:"Labor Code \xA7226.7"},{id:"law-063",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFQu\xE9 ley federal establece el minimum wage y overtime federal?",options:{a:"FLSA, Fair Labor Standards Act federal desde 1938",b:"FMLA, Family and Medical Leave Act del a\xF1o 1993",c:"OSH Act, creando OSHA como agencia federal safety",d:"ADA, Americans with Disabilities Act promulgada"},correct:"a",explanation:"El FLSA establece est\xE1ndares federales de minimum wage, overtime, child labor y recordkeeping. En CA se aplica el m\xE1s beneficioso entre FLSA y CA law \u2014 generalmente CA es m\xE1s estricto.",reference:"29 U.S.C. \xA7201 et seq."},{id:"law-064",category:"Empleo y Payroll",difficulty:"medium",question:"\xBFQu\xE9 es la AB 1228 y como afecta a contratistas?",options:{a:"Ley fast food $20/h; no afecta construcci\xF3n directo",b:"Requiere bond adicional de $100k a contratistas CSLB",c:"Elimina prevailing wage en proyectos escolares K-12",d:"Crea nueva clasificaci\xF3n de licencia de solar C-46"},correct:"a",explanation:"AB 1228 establece $20/hr minimum wage para fast food (2024), no afecta directamente contratistas. Es mencionada aqui para distinguir \u2014 para contratistas residential/commercial aplica $16/hr state minimum y prevailing wage en public works.",reference:"Labor Code \xA71474 (AB 1228)"},{id:"law-065",category:"Empleo y Payroll",difficulty:"easy",question:"\xBFQu\xE9 formulario federal anual reporta wages e impuestos retenidos a empleados?",options:{a:"1099-NEC, para contratistas independientes pagados",b:"W-2, Wage and Tax Statement anual al empleado",c:"W-3, transmittal summary al SSA solamente usado",d:"941, Employer's Quarterly Federal Tax Return"},correct:"b",explanation:"El W-2 (Wage and Tax Statement) se emite anualmente a cada empleado antes del 31 de enero, reportando wages y retenciones. El W-3 es el summary transmittal al SSA con copia de todos los W-2s.",reference:"IRS Form W-2 instructions"},{id:"law-066",category:"Bonds, Seguros y Liens",difficulty:"easy",question:"\xBFCu\xE1l es el monto m\xEDnimo del contractor's bond exigido por CSLB (desde enero 2023)?",options:{a:"$10,000, monto hist\xF3rico de pre-2007 en CA",b:"$15,000, vigente durante 2007 hasta 2016 en CSLB",c:"$25,000, m\xEDnimo actual exigido desde enero 2023",d:"$50,000, aplica \xFAnicamente a LLCs con licencia"},correct:"c",explanation:"Desde enero 2023, CSLB exige un contractor's bond m\xEDnimo de $25,000. Este bond protege a clientes, empleados y el estado contra incumplimientos del contratista (no es seguro del contratista).",reference:"B&P Code \xA77071.6"},{id:"law-067",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFA qui\xE9n protege el contractor's bond?",options:{a:"Al contratista contra demandas de clientes",b:"A consumidores, empleados por wages, y al estado",c:"\xDAnicamente a CSLB contra fees no pagados",d:"Solo a subcontratistas por pagos del prime"},correct:"b",explanation:"El contractor's bond protege: 1) consumidores por incumplimiento o trabajo defectuoso, 2) empleados por wages no pagados, 3) al estado de California. NO protege al contratista de demandas \u2014 para eso es seguro de liability.",reference:"B&P Code \xA77071.5"},{id:"law-068",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es el Bond of Qualifying Individual (BQI)?",options:{a:"Segundo contractor's bond emitido por surety carrier",b:"Bond $25,000 cuando qualifier no es due\xF1o mayoritario",c:"Bond requerido para toda empresa con 2+ socios",d:"Bond del subcontratista hacia el prime contractor"},correct:"b",explanation:"El BQI es un bond adicional de $25,000 requerido cuando el Responsible Managing Individual (RMO/RME) no es due\xF1o del 10%+ de la empresa. Protege contra abandonment por parte del qualifier.",reference:"B&P Code \xA77071.9"},{id:"law-069",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es un 'disciplinary bond'?",options:{a:"Bond est\xE1ndar para aplicar licencia nueva por primera vez",b:"Bond elevado impuesto por CSLB tras violaciones previas",c:"Performance bond requerido por owners de obra p\xFAblica",d:"Bond federal emitido por Miller Act en obra federal"},correct:"b",explanation:"Un disciplinary bond es impuesto por CSLB a licencias con historial disciplinario, reemplazando o aumentando el contractor's bond est\xE1ndar. El monto depende de la violacion, puede llegar a $100,000 o m\xE1s.",reference:"B&P Code \xA77071.8"},{id:"law-070",category:"Bonds, Seguros y Liens",difficulty:"easy",question:"\xBFQu\xE9 tipo de seguro cubre da\xF1os a terceros causados por tu trabajo?",options:{a:"Workers' compensation, cubre lesiones de empleados",b:"General liability insurance, da\xF1os a terceros y property",c:"Health insurance grupal de empleados del contratista",d:"Auto insurance comercial para flota de veh\xEDculos"},correct:"b",explanation:"General Liability insurance cubre da\xF1os a terceros (property damage, bodily injury) causados por operaciones del contratista. No es requerido por CSLB en general, pero casi todos los clientes comerciales lo exigen.",reference:"Insurance industry standard"},{id:"law-071",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFDesde cu\xE1ndo CSLB requiere general liability insurance para contratistas con licencia?",options:{a:"Desde 1982, para todo contratista con licencia CA",b:"Desde enero 2023, \xFAnicamente para roofers C-39",c:"No requerido en general; s\xED para LLCs bajo \xA77071.19",d:"Solo aplica a contratistas en proyectos prevailing wage"},correct:"c",explanation:"CSLB no requiere general liability insurance para contratistas est\xE1ndar, pero SI para LLCs ($1M m\xEDnimo, m\xE1s $100k por cada $1M sobre $5M en gross revenue). Clientes privados y publicos suelen exigirlo.",reference:"B&P Code \xA77071.19"},{id:"law-072",category:"Bonds, Seguros y Liens",difficulty:"hard",question:"\xBFCu\xE1l es el monto m\xEDnimo de general liability insurance para una LLC con licencia CSLB?",options:{a:"$500,000, l\xEDmite aplicable solo a sole proprietors",b:"$1,000,000, m\xE1s escalonado seg\xFAn ingresos brutos",c:"$2,000,000, requerido para contratos federales Miller",d:"$5,000,000, agregado m\xE1ximo por p\xF3liza anual vigente"},correct:"b",explanation:"LLCs con licencia CSLB requieren m\xEDnimo $1,000,000 general liability insurance, m\xE1s $100,000 adicionales por cada $1M de ingresos brutos sobre $5M, hasta $5M agregado m\xE1ximo.",reference:"B&P Code \xA77071.19"},{id:"law-073",category:"Bonds, Seguros y Liens",difficulty:"easy",question:"\xBFQu\xE9 es un 'mechanic's lien'?",options:{a:"Pr\xE9stamo bancario garantizado con la propiedad construida",b:"Derecho legal de reclamar pago sobre la propiedad trabajada",c:"Tipo de bond surety emitido por aseguradora privada",d:"Seguro property damage del contratista en obra activa"},correct:"b",explanation:"Un mechanic's lien es un derecho legal que permite a contratistas, subs, trabajadores y proveedores que no han sido pagados reclamar la propiedad como garantia, pudiendo forzar su venta via foreclosure.",reference:"Civil Code \xA78400 et seq."},{id:"law-074",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFDentro de cuantos dias del INICIO del trabajo debe servirse el preliminary notice (20-day notice)?",options:{a:"10 d\xEDas, plazo federal del Miller Act public works",b:"20 d\xEDas desde el primer trabajo o entrega de materiales",c:"30 d\xEDas, plazo hist\xF3rico vigente antes de 2012 en CA",d:"60 d\xEDas, coincidiendo con Notice of Completion plazo"},correct:"b",explanation:"El preliminary notice (antes 20-day notice) debe servirse dentro de 20 d\xEDas del primer trabajo o entrega de materiales. Sin preliminary notice valido, subs y suppliers pierden su derecho a mechanic's lien en la mayoria de casos.",reference:"Civil Code \xA78204"},{id:"law-075",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQui\xE9n est\xE1 EXENTO de dar preliminary notice?",options:{a:"Todo contratista que tenga contrato escrito firmado",b:"El direct contractor, respecto al owner (no al lender)",c:"Los subcontratistas con contratos mayores a $50,000",d:"Los trabajadores individuales por unpaid wages solos"},correct:"b",explanation:"El prime contractor (direct contractor) que contrata directamente con el due\xF1o NO necesita dar preliminary notice al due\xF1o (ya tiene contrato). PERO debe darlo a construction lender si hay uno. Subs y suppliers si deben darlo.",reference:"Civil Code \xA78200"},{id:"law-076",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFDentro de cuantos dias despu\xE9s de completion del proyecto debe file un mechanic's lien el PRIME contractor?",options:{a:"30 d\xEDas, plazo aplicable a subcontratistas con NoC",b:"60 d\xEDas, plazo si el due\xF1o records Notice of Completion",c:"90 d\xEDas desde completion, sin Notice of Completion",d:"120 d\xEDas, plazo extendido por agreement con owner"},correct:"c",explanation:"El prime contractor tiene 90 d\xEDas despu\xE9s de completion del proyecto entero para file mechanic's lien. Si el due\xF1o records Notice of Completion, el prime contractor tiene solo 60 d\xEDas desde ese filing.",reference:"Civil Code \xA78412"},{id:"law-077",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"Si se records un Notice of Completion, \xBFcuantos dias tiene un SUBCONTRACTOR para file mechanic's lien?",options:{a:"15 d\xEDas, plazo reducido si hay Notice of Cessation",b:"30 d\xEDas desde la fecha de recording del Notice",c:"60 d\xEDas, plazo aplicable al prime contractor con NoC",d:"90 d\xEDas desde completion, si no se grab\xF3 Notice"},correct:"b",explanation:"Con Notice of Completion recorded, subs y suppliers tienen solo 30 d\xEDas para file lien. Sin Notice of Completion, tienen 90 d\xEDas desde completion. Por esto el Notice of Completion protege al due\xF1o acortando plazos.",reference:"Civil Code \xA78414"},{id:"law-078",category:"Bonds, Seguros y Liens",difficulty:"hard",question:"Despu\xE9s de filing mechanic's lien, \xBFcuanto tiempo tienes para iniciar foreclosure lawsuit?",options:{a:"30 d\xEDas, plazo abreviado si propiedad en foreclosure",b:"60 d\xEDas desde el recording inicial del lien document",c:"90 d\xEDas desde recording, salvo extensi\xF3n por acuerdo",d:"180 d\xEDas, plazo federal para liens Miller Act claims"},correct:"c",explanation:"Despu\xE9s de recording mechanic's lien, tienes 90 d\xEDas para iniciar demanda de foreclosure. Si no lo haces, el lien expira y debes release. Puede extenderse via agreement scrito con owner.",reference:"Civil Code \xA78460"},{id:"law-079",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es un 'stop payment notice' (antes llamado stop notice)?",options:{a:"Versi\xF3n formal del mechanic's lien para propiedad privada",b:"Aviso a lender u owner para retener fondos del prime",c:"Tipo de payment bond emitido por surety carrier",d:"Subpoena judicial bajo Code of Civil Procedure"},correct:"b",explanation:"Stop payment notice es un aviso legal que subs/suppliers pueden enviar al construction lender o al due\xF1o, obligandolos a retener fondos del payment al prime contractor. Funciona en paralelo al mechanic's lien.",reference:"Civil Code \xA78500 et seq."},{id:"law-080",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"En obra p\xFAblica, \xBFqu\xE9 reemplaza al mechanic's lien (ya que propiedad p\xFAblica no se puede lienar)?",options:{a:"Nada, el sub pierde derechos en obra p\xFAblica",b:"Stop payment notice y claim contra payment bond",c:"\xDAnicamente demanda directa contra el public entity",d:"Arbitration forzosa ante DIR Labor Commissioner"},correct:"b",explanation:"Propiedad p\xFAblica NO se puede lienar. En obra p\xFAblica los remedios son: 1) Stop Payment Notice al public entity, y 2) Claim contra el payment bond del prime contractor. Por eso payment bonds son requeridos en public works.",reference:"Civil Code \xA79000 et seq."},{id:"law-081",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es un 'payment bond' en public works?",options:{a:"Bond que garantiza pago del owner al prime contractor",b:"Bond que garantiza pago a subs, suppliers y trabajadores",c:"Dep\xF3sito en escrow retenido por el public entity",d:"Performance bond sobre el cumplimiento del contrato"},correct:"b",explanation:"El payment bond garantiza que subs, suppliers y trabajadores seran pagados por el prime contractor en un public works project. Requerido para proyectos publicos >$25,000. Protege contra abandon del prime.",reference:"Civil Code \xA79550 et seq."},{id:"law-082",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es un 'performance bond'?",options:{a:"Bond que garantiza pago a subs, suppliers y workers",b:"Bond que garantiza completion del trabajo per contrato",c:"Bond de lealtad (fidelity) contra robo por empleados",d:"Bond CSLB del contratista para operar en California"},correct:"b",explanation:"Performance bond garantiza que el contratista cumplir\xE1 el contrato. Si abandona o falla, el surety indemniza al owner hasta el monto del bond (usualmente 100% del contract value). Comun en public works.",reference:"Public Contract Code \xA710221"},{id:"law-083",category:"Bonds, Seguros y Liens",difficulty:"hard",question:"\xBFEn proyecto p\xFAblico estatal, cual es el monto m\xEDnimo de performance y payment bonds?",options:{a:"50% del contrato cada uno, per c\xF3digo hist\xF3rico 1975",b:"100% del contrato para ambos performance y payment",c:"$25,000 fijo, umbral de bonding en CA public works",d:"$100,000 fijo, LLC threshold en CSLB code \xA77071.19"},correct:"b",explanation:"En obra p\xFAblica estatal mayor a $25,000, se requieren ambos: performance bond (100% del contrato) y payment bond (100% del contrato). Esto protege al public entity y a los que trabajaron y suministraron.",reference:"Public Contract Code \xA710221 / Civil Code \xA79550"},{id:"law-084",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFPara cobrar mechanic's lien, el contratista debe haber tenido licencia CSLB valida en cual momento?",options:{a:"\xDAnicamente al firmar el contrato inicial con el owner",b:"Durante toda la duraci\xF3n del trabajo sin interrupci\xF3n",c:"Solamente al momento de recording del lien document",d:"No es requerida licencia para reclamar mechanic's lien"},correct:"b",explanation:"El contratista debe haber estado LICENCIADO durante toda la duracion del trabajo para preservar su derecho a demandar o ejecutar mechanic's lien. Si la licencia estuvo suspendida en algun momento, pierde derecho a cobrar.",reference:"B&P Code \xA77031"},{id:"law-085",category:"Bonds, Seguros y Liens",difficulty:"hard",question:"Bajo B&P \xA77031, si un contratista trabaja sin licencia, \xBFqu\xE9 puede recuperar el cliente?",options:{a:"Nada, el contrato verbal sigue siendo ejecutable",b:"Disgorgement: devoluci\xF3n total de lo pagado al contratista",c:"\xDAnicamente diferencia entre lo pagado y valor justo",d:"Solo da\xF1os punitivos si hubo fraude afirmativamente probado"},correct:"b",explanation:"B&P \xA77031 permite al cliente demandar devolucion de TODO lo que pago al contratista sin licencia \u2014 una de las leyes mas severas del pa\xEDs. Trabajo sin licencia es un riesgo financiero enorme.",reference:"B&P Code \xA77031"},{id:"law-086",category:"Bonds, Seguros y Liens",difficulty:"easy",question:"\xBFQu\xE9 tipo de seguro es OBLIGATORIO para vehiculos comerciales en California?",options:{a:"Comprehensive only, cubre da\xF1o a propio veh\xEDculo solo",b:"Liability m\xEDnimo establecido por CA DMV y Veh Code",c:"Ning\xFAn seguro es obligatorio para veh\xEDculos propios",d:"Solo aplica si flota comercial supera cinco veh\xEDculos"},correct:"b",explanation:"California exige minimum liability insurance para cualquier vehiculo registered. Para commercial vehicles puede requerirse cobertura mas alta. Muchos clientes commercial exigen $1M combined single limit.",reference:"CA Vehicle Code \xA716020"},{id:"law-087",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es 'umbrella insurance' en contexto de contratistas?",options:{a:"Seguro contra da\xF1os por lluvia y eventos clim\xE1ticos",b:"Cobertura excess sobre otras p\xF3lizas cuando se agotan",c:"Workers' comp extendido para subs independientes 1099",d:"Bond surety emitido encima del contractor's bond"},correct:"b",explanation:"Umbrella policy provee cobertura adicional (ej. $1M-$10M) que se activa cuando la general liability, auto o employer liability se agotan. \xDAtil para protegerse contra claims grandes en construccion.",reference:"Insurance industry standard"},{id:"law-088",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es 'inland marine insurance' para contratistas?",options:{a:"Cobertura mar\xEDtima para transporte de carga v\xEDa oc\xE9ano",b:"Cobertura de equipo y herramientas fuera del shop",c:"Seguro de carga comercial en tr\xE1nsito interestatal",d:"Cobertura de oficina contra robo y vandalismo local"},correct:"b",explanation:"Inland marine insurance (pese a su nombre) cubre equipo y herramientas del contratista mientras estan en transito o en sitios de trabajo. La general liability no cubre tu propio equipo.",reference:"Insurance industry standard"},{id:"law-089",category:"Bonds, Seguros y Liens",difficulty:"easy",question:"\xBFUn contratista sin empleados, operando como sole prop, necesita workers' comp?",options:{a:"S\xED, siempre, sin excepciones por tipo de licencia",b:"No en general; s\xED los C-39 roofers desde 2011",c:"Solo si sus ingresos anuales superan $100,000",d:"\xDAnicamente si trabaja en public works prevailing wage"},correct:"b",explanation:"Sole props sin empleados generalmente NO necesitan workers' comp (ellos no son 'empleados' de si mismos). EXCEPCION: C-39 roofers deben tener workers' comp desde 2011 aunque no tengan empleados.",reference:"Labor Code \xA73351 / B&P \xA77125(c)"},{id:"law-090",category:"Bonds, Seguros y Liens",difficulty:"hard",question:"Si el contratista no mantiene workers' comp cuando es requerido, \xBFqu\xE9 accion toma CSLB?",options:{a:"Warning verbal y carta de cumplimiento en 30 d\xEDas",b:"Suspensi\xF3n autom\xE1tica de licencia hasta probar cobertura",c:"Multa de $500 administrativa, sin afectar status licencia",d:"Revocaci\xF3n inmediata permanente, sin derecho a reinstatement"},correct:"b",explanation:"Si CSLB recibe notice de cancelacion de workers' comp, suspende automaticamente la licencia hasta que se demuestre cobertura valida o exemption. Trabajar con licencia suspendida es operar sin licencia.",reference:"B&P Code \xA77125.2"},{id:"law-091",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 pasa si un trabajador se lesiona y no hay workers' comp?",options:{a:"Nada, el trabajador absorbe costos m\xE9dicos personales",b:"Empleador responde ilimitado: medical, disability, penalties",c:"El estado cubre la lesi\xF3n v\xEDa CA Uninsured Employers Fund",d:"El trabajador mismo paga de su bolsillo los tratamientos"},correct:"b",explanation:"Sin workers' comp, el empleador enfrenta responsabilidad ILIMITADA por medical costs, lost wages, disability, ademas de penalties de $10,000 por empleado y posible prison. Puede quebrar al negocio completo.",reference:"Labor Code \xA73700 et seq."},{id:"law-092",category:"Bonds, Seguros y Liens",difficulty:"medium",question:"\xBFQu\xE9 es una 'conditional waiver and release' de lien?",options:{a:"Waiver permanente e incondicional al recibir cheque",b:"Waiver efectivo solo cuando el pago realmente clears",c:"Waiver firmado sin recibir pago alguno adelantado",d:"Bond surety que sustituye al derecho de lien otorgado"},correct:"b",explanation:"Conditional waiver se firma al recibir cheque pero es efectivo SOLO cuando el cheque clears. Protege al contratista si el cheque rebota. Unconditional waiver es efectivo inmediatamente \u2014 no firmar hasta haber cobrado.",reference:"Civil Code \xA78132-8138"},{id:"law-093",category:"Contratos",difficulty:"easy",question:"\xBFQu\xE9 monto de contrato home improvement requiere que sea por ESCRITO en California?",options:{a:"Cualquier monto, a\xFAn si es menor a $100 d\xF3lares",b:"$500 o m\xE1s, combinando labor y materiales totales",c:"$1,000 o m\xE1s, umbral anterior al cambio de 2005",d:"$5,000 o m\xE1s, umbral aplicable a obra comercial solo"},correct:"b",explanation:"Cualquier home improvement contract de $500 o m\xE1s (labor + materiales) DEBE ser por escrito en California. Contratos orales de este monto son violacion B&P \xA77159 y pueden resultar en disciplina.",reference:"B&P Code \xA77159"},{id:"law-094",category:"Contratos",difficulty:"medium",question:"\xBFQu\xE9 debe incluir un home improvement contract bajo B&P \xA77159?",options:{a:"Solamente el precio total y la firma de ambas partes",b:"Nombre, licencia, scope, precio, schedule, right to cancel",c:"\xDAnicamente firma notarizada y descripci\xF3n general del trabajo",d:"Un bond adjuntado como endoso al contrato principal firmado"},correct:"b",explanation:"B&P \xA77159 requiere: nombre legal, numero y clasificacion de licencia, direccion, fecha, descripcion del trabajo, plans (si aplican), precio, schedule de pagos, start/completion dates, notice of cancelacion.",reference:"B&P Code \xA77159"},{id:"law-095",category:"Contratos",difficulty:"medium",question:"\xBFCu\xE1l es el maximo down payment permitido en home improvement contracts?",options:{a:"50% del contrato total o $5,000, lo que sea menor",b:"25% del contrato total al momento de la firma inicial",c:"10% del contrato o $1,000, lo que sea menor aplica",d:"No hay l\xEDmite espec\xEDfico en el B&P Code \xA77159"},correct:"c",explanation:"En home improvement contracts, el down payment m\xE1ximo es 10% del precio total O $1,000, lo que sea MENOR. Exceder esto es violacion de B&P \xA77159. Excepcion: contratos con bond posted or escrow.",reference:"B&P Code \xA77159(d)"},{id:"law-096",category:"Contratos",difficulty:"medium",question:"\xBFCu\xE1l es el periodo de 'right to cancel' (3-day notice) en home improvement contracts?",options:{a:"1 d\xEDa h\xE1bil desde la firma del contrato inicial",b:"3 d\xEDas h\xE1biles desde la firma, notice requerido",c:"7 d\xEDas calendario en contratos de solar \xFAnicamente",d:"10 d\xEDas h\xE1biles aplicables a contratos de refinanciamiento"},correct:"b",explanation:"El cliente tiene 3 d\xEDas h\xE1biles para cancelar home improvement contract sin penalidad. Debe darsele written notice of cancelacion al firmar. Para seniors (65+), el periodo es 5 d\xEDas h\xE1biles.",reference:"B&P Code \xA77159(e)"},{id:"law-097",category:"Contratos",difficulty:"hard",question:"\xBFCu\xE1l es el right-to-cancel para clientes SENIORS (65 a\xF1os o mas) en home improvement?",options:{a:"3 d\xEDas h\xE1biles, igual al est\xE1ndar de todo cliente",b:"5 d\xEDas h\xE1biles, proteccion adicional contra abuse",c:"7 d\xEDas calendario, aplicable bajo federal FTC rule",d:"10 d\xEDas h\xE1biles, regla de finance por lenders solo"},correct:"b",explanation:"Clientes de 65 a\xF1os o m\xE1s tienen 5 d\xEDas h\xE1biles para cancelar en vez de 3. Es proteccion adicional para seniors contra practicas depredadoras. Mismo notice debe darse al firmar, ajustado.",reference:"B&P Code \xA77159"},{id:"law-098",category:"Contratos",difficulty:"medium",question:"\xBFQu\xE9 es un 'change order'?",options:{a:"Cambio de clasificaci\xF3n de licencia CSLB del contratista",b:"Modificaci\xF3n escrita al contrato por cambios de scope o precio",c:"Orden de compra al proveedor de materiales adicionales",d:"Cancelaci\xF3n formal del contrato por mutual rescission"},correct:"b",explanation:"Change order es una modificacion escrita al contrato original, documentando cambios en scope, materiales, schedule o precio. Debe firmarse por ambas partes ANTES de ejecutar el cambio. Protege de disputes.",reference:"Construction Industry Practice / B&P \xA77159"},{id:"law-099",category:"Contratos",difficulty:"medium",question:"\xBFUn change order verbal es legalmente v\xE1lido?",options:{a:"S\xED, siempre, bajo common law parol evidence rule",b:"Puede ser enforceable pero best practice es escrito",c:"Nunca es v\xE1lido, incluso con prueba de performance",d:"\xDAnicamente v\xE1lido si el monto adicional es bajo $500"},correct:"b",explanation:"Change orders verbales pueden ser enforceable pero son fuente principal de disputes. Best practice: todo change order por escrito, firmado por due\xF1o, antes de ejecutar. En home improvement es requisito legal.",reference:"B&P Code \xA77159 / Contract Law"},{id:"law-100",category:"Contratos",difficulty:"medium",question:"\xBFQu\xE9 es 'liquidated damages' en un contrato?",options:{a:"Indemnizaci\xF3n pre-acordada por breach espec\xEDfico del contrato",b:"Da\xF1os reales determinados por un jurado despu\xE9s de juicio",c:"Multa penal impuesta por CSLB por incumplimiento contractual",d:"Compensaci\xF3n por lesiones corporales sufridas por empleados"},correct:"a",explanation:"Liquidated damages son montos pre-acordados en el contrato como compensacion por breach espec\xEDfico (comunmente delay). Debe ser razonable estimate del da\xF1o real, no una penalizacion excesiva.",reference:"Civil Code \xA71671"},{id:"law-101",category:"Contratos",difficulty:"medium",question:"\xBFQu\xE9 significa 'time is of the essence' en un contrato?",options:{a:"El tiempo no es material; delays menores no son breach",b:"Deadlines son esenciales; incumplimiento es breach material",c:"Hay 90 d\xEDas despu\xE9s de completion para pagar facturas",d:"El contrato caduca un a\xF1o despu\xE9s de la firma inicial"},correct:"b",explanation:"Clausula 'time is of the essence' hace que el cumplimiento de fechas sea esencial al contrato. Missing un deadline es breach material permitiendo termination y damages. Sin esta clausula, delays menores usualmente no son breach.",reference:"Contract Law / Civil Code"},{id:"law-102",category:"Contratos",difficulty:"easy",question:"\xBFUn contrato de construccion puede tener clausula de arbitration?",options:{a:"No, las clausulas de arbitration son ilegales en CA",b:"S\xED, comunes; obligan resolver disputes via arbitrator",c:"\xDAnicamente en contratos comerciales de $1M o m\xE1s",d:"Solo si el cliente lo solicita expresamente por escrito"},correct:"b",explanation:"Clausulas de arbitration son validas y comunes en contratos de construccion. Obligan a resolver disputes via arbitrator privado en vez de corte. Debe ser claramente mostrada en home improvement (initials).",reference:"CCP \xA71280 et seq. / B&P \xA77159"},{id:"law-103",category:"Contratos",difficulty:"medium",question:"\xBFQu\xE9 es un 'lien waiver' firmado por el contratista?",options:{a:"Renuncia al derecho de mechanic's lien a cambio de pago",b:"Autorizaci\xF3n escrita del owner permitiendo recording de lien",c:"Tipo de surety bond emitido por aseguradora a favor owner",d:"Change order documentando scope adicional del proyecto"},correct:"a",explanation:"Lien waiver es documento donde contratista/sub/supplier renuncia a su derecho de mechanic's lien a cambio de pago recibido. Puede ser conditional (efectivo al clear cheque) o unconditional (efectivo inmediato).",reference:"Civil Code \xA78120-8138"},{id:"law-104",category:"Contratos",difficulty:"hard",question:"Si un contratista firma un waiver de lien UNCONDITIONAL y el cheque rebota, \xBFpuede aun lienar?",options:{a:"S\xED, autom\xE1ticamente revive el derecho si cheque rebota",b:"No; perdi\xF3 el derecho y debe cobrar como acreedor general",c:"Solo si el monto adeudado supera los $10,000 d\xF3lares",d:"S\xED, con extensi\xF3n adicional de 30 d\xEDas para el filing"},correct:"b",explanation:"Unconditional waiver es efectivo INMEDIATAMENTE al firmar, incluso si pago no se recibe o rebota. Por eso nunca firmes unconditional waiver hasta que el pago HAYA CASHED. Usa conditional waiver cuando firmas al recibir cheque.",reference:"Civil Code \xA78134 / \xA78138"},{id:"law-105",category:"Contratos",difficulty:"medium",question:"\xBFQu\xE9 es 'indemnification clause' en contratos de construccion?",options:{a:"Bono de desempe\xF1o pagado al empleado por cerrar proyecto",b:"Cl\xE1usula donde una parte protege/reembolsa a otra por losses",c:"P\xF3liza de seguro emitida por aseguradora comercial al prime",d:"Bond surety que garantiza completion del trabajo contratado"},correct:"b",explanation:"Indemnification clause obliga a una parte (indemnitor) a proteger e reembolsar a la otra (indemnitee) por losses espec\xEDficos. En construccion CA, ciertas indemnity son limitadas por ley (no puedes indemnify contra tu propia negligencia).",reference:"Civil Code \xA72782 et seq."},{id:"law-106",category:"Contratos",difficulty:"medium",question:"Bajo Civil Code \xA72782, \xBFqu\xE9 tipo de indemnity es VOID en contratos de construccion residencial?",options:{a:"Toda forma de indemnity es inv\xE1lida en construcci\xF3n residencial",b:"Indemnity que cubre negligencia sola del GC/owner sobre sub",c:"Indemnity rec\xEDproca, ambas partes protegidas mutuamente",d:"Indemnity limitada a da\xF1os materiales durante construcci\xF3n"},correct:"b",explanation:"Civil Code \xA72782 prohibe obligar a un sub o arquitecto a indemnify al GC/owner por la negligencia SOLA o willful misconduct del GC/owner. Proteccion contra 'type I indemnity' en construccion residencial.",reference:"Civil Code \xA72782"},{id:"law-107",category:"Contratos",difficulty:"easy",question:"\xBFQu\xE9 es 'scope of work' en un contrato?",options:{a:"El precio total fijo acordado para completar el proyecto",b:"Descripci\xF3n detallada del trabajo, labor, materiales y entregables",c:"El cronograma de pagos progresivos pactado con el owner",d:"Lista de subcontratistas autorizados a trabajar en el proyecto"},correct:"b",explanation:"Scope of Work (SOW) define con especificidad exactamente que trabajo esta incluido: tareas, materiales, exclusions, deliverables, standards. Ambiguedad en SOW es fuente #1 de disputes. Se espec\xEDfico.",reference:"Construction Industry Practice"},{id:"law-108",category:"Contratos",difficulty:"medium",question:"Si el contrato no especifica payment terms, \xBFqu\xE9 aplica por default?",options:{a:"Net 30 d\xEDas, est\xE1ndar en industria de construcci\xF3n",b:"Payment on demand o dentro de tiempo razonable",c:"Prepayment del 100% antes de iniciar trabajo alguno",d:"Net 90 d\xEDas, plazo extendido para construction work"},correct:"b",explanation:"Sin terminos especificos, common law asume pago 'on demand' o dentro de tiempo razonable. POR ESO siempre especifica payment schedule en escrito: down payment, progress payments, final payment con terms claros.",reference:"Contract Law / UCC"},{id:"law-109",category:"Contratos",difficulty:"hard",question:"\xBFQu\xE9 es 'Prompt Payment Act' de California (privado)?",options:{a:"No existe ley de prompt payment en sector privado CA",b:"Pago a subs en 7 d\xEDas desde owner; 2% mensual tard\xEDo",c:"Aplica \xFAnicamente a contratos public works en estado",d:"Pago obligatorio en 60 d\xEDas desde el invoice submission"},correct:"b",explanation:"Prompt Payment Act (privado) requiere que prime contractors paguen a subs dentro de 7 d\xEDas de recibir pago del owner. Late payments incurren 2% mensual interest. Aplica a contratos privados en CA.",reference:"B&P Code \xA77108.5"},{id:"law-110",category:"Contratos",difficulty:"medium",question:"Si el contrato tiene clausula de 'attorney's fees to prevailing party', \xBFes mutua aun si dice solo una parte?",options:{a:"No, solamente recupera fees la parte expresamente nombrada",b:"S\xED, Civil Code \xA71717 la hace mutua autom\xE1ticamente en CA",c:"Solo si se renegocia el contrato con enmienda bilateral",d:"\xDAnicamente aplica a disputas resueltas v\xEDa arbitration"},correct:"b",explanation:"Civil Code \xA71717 hace cualquier clausula de attorney's fees MUTUA automaticamente en California, aun si el contrato dice solo una parte. Previene clausulas unfair donde solo el drafter puede recuperar fees.",reference:"Civil Code \xA71717"},{id:"law-111",category:"Bidding y Seguridad del Proyecto",difficulty:"easy",question:"\xBFQu\xE9 significa 'lump sum bid'?",options:{a:"Precio total fijo por completar todo el scope del proyecto",b:"Pago por hora de labor m\xE1s materiales con markup acordado",c:"Time and materials, reembolso de costos actuales incurridos",d:"Cost plus con fee porcentual sobre costos documentados"},correct:"a",explanation:"Lump sum bid es un precio total fijo para completar todo el scope definido. El contratista asume riesgo de overruns; owner tiene certeza de precio. Requiere scope muy bien definido para evitar disputes.",reference:"Construction Estimating Principles"},{id:"law-112",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFQu\xE9 es un 'cost-plus' contract?",options:{a:"Precio fijo total acordado antes de iniciar el trabajo",b:"Contratista cobra costo real documentado m\xE1s fee definido",c:"\xDAnicamente Time & Materials con rates por hora pactados",d:"Contrato lump sum con descuento por pronto pago al owner"},correct:"b",explanation:"Cost-plus contract: owner paga los costos reales documentados del contratista + un fee (% o fijo) como ganancia. Bueno para scope incierto. Requiere transparencia y auditing. Puede tener GMP (guaranteed max price).",reference:"Construction Contract Types"},{id:"law-113",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFQu\xE9 es un 'unit price' contract?",options:{a:"Precio total fijo global para todo el scope definido",b:"Precios unitarios por cantidad, ej. yarda c\xFAbica de concreto",c:"Cost plus fee fijo sobre costos reales documentados",d:"Hourly rate por trabajador m\xE1s markup sobre materiales"},correct:"b",explanation:"Unit price: contratista cotiza precio por unidad (yarda cubica, square foot, linear foot). Total se calcula seg\xFAn cantidades reales. Comun en site work donde cantidades son inciertas hasta excavacion.",reference:"Construction Contract Types"},{id:"law-114",category:"Bidding y Seguridad del Proyecto",difficulty:"hard",question:"En public works de California, \xBFqu\xE9 es 'lowest responsible bidder'?",options:{a:"El bidder con el precio m\xE1s bajo gana autom\xE1ticamente el contrato",b:"Bid m\xE1s bajo entre bidders responsable: licencia, bond, record",c:"Selecci\xF3n aleatoria entre los tres bidders m\xE1s competitivos del set",d:"El contratista con mayor reputaci\xF3n o a\xF1os en el rubro p\xFAblico"},correct:"b",explanation:"Lowest RESPONSIBLE bidder: no solo el precio mas bajo, sino el bid mas bajo de un bidder que cumple requisitos de responsibility (licencia, bonding, experiencia, sin violaciones graves). Agencia puede rechazar bidder non-responsible.",reference:"Public Contract Code \xA71103"},{id:"law-115",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFQu\xE9 es un 'bid bond'?",options:{a:"Bond que garantiza que el bidder firmar\xE1 contrato si awarded",b:"Payment bond que protege a subs por pagos del prime contractor",c:"Bond fidelity que protege contra robo por empleados del bidder",d:"Performance bond garantizando completion del trabajo adjudicado"},correct:"a",explanation:"Bid bond garantiza que si el bidder es awarded, firmar\xE1 el contrato y proveer\xE1 performance/payment bonds. Si se rehusa, surety paga diferencia al siguiente bidder. Usualmente 10% del bid amount.",reference:"Public Contract Code \xA720170"},{id:"law-116",category:"Bidding y Seguridad del Proyecto",difficulty:"hard",question:"En California public works, \xBFcu\xE1l es el monto de proyecto que dispara el requisito de prevailing wage?",options:{a:"$1,000 en obra p\xFAblica general estatal y local",b:"$1,000 en obra p\xFAblica; $15,000 para ciertos maintenance",c:"$25,000, umbral de bonding obligatorio en CA public works",d:"$100,000, aplicable solo a proyectos estatales grandes"},correct:"b",explanation:"Prevailing wage se requiere en public works $1,000+ generalmente. Maintenance tiene umbral m\xE1s alto ($15,000-$25,000 seg\xFAn tipo). DIR publica prevailing wage rates por craft y locality.",reference:"Labor Code \xA71771 / \xA71771.5"},{id:"law-117",category:"Bidding y Seguridad del Proyecto",difficulty:"easy",question:"\xBFQu\xE9 agencia federal regula safety en workplaces?",options:{a:"EPA, Environmental Protection Agency, bajo US Gov",b:"OSHA, Occupational Safety and Health Administration",c:"FBI, Federal Bureau of Investigation bajo DOJ federal",d:"CDC, Centers for Disease Control en Atlanta USA"},correct:"b",explanation:"OSHA es la agencia federal bajo Department of Labor que regula safety ocupacional. California opera Cal/OSHA (state plan), con reglas generalmente mas estrictas que federal OSHA.",reference:"29 U.S.C. \xA7651 et seq."},{id:"law-118",category:"Bidding y Seguridad del Proyecto",difficulty:"easy",question:"\xBFCu\xE1l es la altura a la que se requiere fall protection en construccion bajo Cal/OSHA?",options:{a:"4 pies, est\xE1ndar general industry bajo Federal OSHA",b:"6 pies, umbral del Federal OSHA en construction work",c:"7.5 pies, umbral espec\xEDfico de Cal/OSHA m\xE1s estricto",d:"10 pies, solo para trabajos de roofing residential C-39"},correct:"c",explanation:"Cal/OSHA requiere fall protection en construccion desde 7.5 pies (Federal OSHA es 6 pies). M\xE9todos aceptables: guardrails, safety nets, personal fall arrest systems (PFAS). Falls son causa #1 de muertes en construccion.",reference:"CCR Title 8 \xA71670"},{id:"law-119",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFCuantas horas de OSHA safety training requiere California para supervisores de construccion?",options:{a:"No hay requerimiento espec\xEDfico de horas en CA law",b:"OSHA 30 est\xE1ndar industria; Cal/OSHA exige IIPP training",c:"OSHA 10 m\xEDnimo, igual que para workers comunes en sitio",d:"100 horas de training anual en safety y IIPP combinado"},correct:"b",explanation:"Cal/OSHA requiere IIPP (Injury and Illness Prevention Program) training para todos. OSHA 30 es estandar de industria (y a veces required por contrato) para supervisores. OSHA 10 para workers comunes.",reference:"CCR Title 8 \xA73203"},{id:"law-120",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFQu\xE9 es el IIPP (Injury and Illness Prevention Program)?",options:{a:"Plan de retiro 401(k) ofrecido a empleados del contratista",b:"Programa escrito obligatorio de prevenci\xF3n de lesiones en job",c:"Seguro m\xE9dico grupal obligatorio para empleados full-time",d:"Workers' comp con opci\xF3n de self-insurance aprobada por DIR"},correct:"b",explanation:"IIPP es un programa escrito OBLIGATORIO para todo empleador en California. Debe incluir: persona responsable, sistema de compliance, comunicacion, hazard assessment, investigacion de accidentes, training, recordkeeping.",reference:"CCR Title 8 \xA73203"},{id:"law-121",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"Si un empleado es lesionado seriamente, \xBFdentro de cuantas horas debe reportarse a Cal/OSHA?",options:{a:"24 horas para serious injury bajo federal OSHA rule",b:"8 horas para serious injury, fatality o hospitalizaci\xF3n",c:"48 horas, aplicable solo a lesiones de menor gravedad",d:"Una semana completa desde ocurrido el incidente laboral"},correct:"b",explanation:"Serious injuries, illnesses y deaths deben reportarse a Cal/OSHA dentro de 8 HORAS. Serious injury incluye hospitalization inpatient, amputation, loss of eye. No hacerlo tiene penalties grandes.",reference:"CCR Title 8 \xA7342"},{id:"law-122",category:"Bidding y Seguridad del Proyecto",difficulty:"easy",question:"\xBFQu\xE9 significa PPE?",options:{a:"Private Practice Equipment, uso profesional individual",b:"Personal Protective Equipment, equipo protecci\xF3n personal",c:"Public Project Estimate, estimaci\xF3n de obra p\xFAblica prevail",d:"Prime Pay Equity, equidad salarial entre prime contractors"},correct:"b",explanation:"PPE = Personal Protective Equipment: hard hats, safety glasses, gloves, hearing protection, respirators, harnesses, boots. Empleador debe proveer PPE adecuado y entrenar en su uso. Requerido por Cal/OSHA.",reference:"CCR Title 8 \xA73380 et seq."},{id:"law-123",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFQui\xE9n paga el PPE \u2014 empleador o empleado?",options:{a:"Empleado siempre paga su propio PPE b\xE1sico y especializado",b:"Empleador, salvo excepciones como steel-toed boots shared",c:"El gobierno estatal subsidia PPE via programa Cal/OSHA directo",d:"El workers' comp insurance carrier reembolsa ambos \xEDtems"},correct:"b",explanation:"Empleador debe proveer PPE sin costo al empleado, con excepciones limitadas como steel-toed boots que usa fuera de trabajo. Cal/OSHA es especifico: harness, hard hats, gloves \u2014 empleador paga.",reference:"CCR Title 8 \xA73380"},{id:"law-124",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"\xBFQu\xE9 es 'competent person' en OSHA?",options:{a:"Cualquier empleado con training b\xE1sico de OSHA 10 o m\xE1s",b:"Designado capaz de identificar hazards, con autoridad correctiva",c:"El supervisor general del proyecto sin training espec\xEDfico",d:"El safety officer corporativo del prime contractor \xFAnicamente"},correct:"b",explanation:"Competent person es designado por el empleador, capaz de identificar hazards existentes o predecibles en el lugar de trabajo, y con AUTORIDAD para tomar medidas correctivas prontas. Requerido para excavation, scaffolding, fall protection.",reference:"29 CFR 1926.32 / CCR Title 8"},{id:"law-125",category:"Bidding y Seguridad del Proyecto",difficulty:"easy",question:"\xBFDesde que profundidad una trench requiere proteccion (shoring, sloping, shielding)?",options:{a:"2 pies, est\xE1ndar en obra residencial bajo Cal/OSHA code",b:"3 pies, profundidad m\xEDnima para permit de excavaci\xF3n CA",c:"5 pies, requiere sloping, shoring o shielding sistem\xE1tico",d:"7 pies, umbral anterior al cambio reglamentario del 1995"},correct:"c",explanation:"Trench de 5 pies o m\xE1s profunda requiere sistema de proteccion (sloping, shoring, or shielding) a menos que sea roca estable. Entre 5-20 pies puede usarse tabulated data; >20 pies requiere engineered design.",reference:"CCR Title 8 \xA71541.1"},{id:"law-126",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"En un jobsite, \xBFqui\xE9n es responsable overall de safety bajo 'multi-employer' doctrine?",options:{a:"\xDAnicamente el General Contractor por todos los trabajadores",b:"Solo los subs, cada uno por sus propios empleados directamente",c:"Cada empleador por sus workers; GC es controlling employer",d:"No hay responsabilidad compartida espec\xEDfica; solo individual"},correct:"c",explanation:"Multi-employer citation policy (OSHA): cada empleador es responsable por sus propios empleados. Adicionalmente GC tiene 'controlling employer' responsibility general del sitio. Subs pueden ser 'exposing' or 'creating' employers.",reference:"OSHA Multi-Employer Citation Policy (CPL 02-00-124)"},{id:"law-127",category:"Bidding y Seguridad del Proyecto",difficulty:"hard",question:"\xBFCu\xE1l es la penalidad maxima por violacion willful de Cal/OSHA en 2024?",options:{a:"$500 m\xE1ximo por violaci\xF3n, est\xE1ndar no-serious hist\xF3rico",b:"$1,000 por violaci\xF3n, tope pre-inflation adjustment 2016",c:"Aprox $158,727 por willful/repeat, ajustado inflaci\xF3n 2024",d:"$5,000 fijo, tope general serious violation en CCR T\xEDtulo 8"},correct:"c",explanation:"Penalties de Cal/OSHA se ajustan anualmente por inflacion. Willful/repeat violations en 2024 pueden llegar a ~$158,000. Serious violations hasta ~$15,000. Failure to abate tambien tiene penalties diarias.",reference:"Labor Code \xA76428 et seq."},{id:"law-128",category:"Bidding y Seguridad del Proyecto",difficulty:"medium",question:"Si bid es 'firm for 30 days', \xBFqu\xE9 significa?",options:{a:"El bid puede retirarse en cualquier momento sin penalidad",b:"Bid irrevocable por 30 d\xEDas; debes honrarlo si acceptado",c:"Expira autom\xE1ticamente en 24 horas sin aviso del owner",d:"Es \xFAnicamente una estimaci\xF3n no vinculante para el contratista"},correct:"b",explanation:"Bid 'firm for 30 days' es irrevocable durante ese periodo. Si owner acepta dentro de 30 d\xEDas, el bidder est\xE1 obligado a cumplir el precio. En public works suele ser 60-90 d\xEDas segun especs del bid package.",reference:"Contract Law / Public Contract Code"},{id:"law-129",category:"Obras P\xFAblicas",difficulty:"easy",question:"\xBFQu\xE9 es 'prevailing wage'?",options:{a:"El minimum wage federal bajo FLSA y sus regulaciones",b:"Tasa de DIR por craft y locality en public works projects",c:"Promedio estad\xEDstico de wages del \xE1rea metropolitana dada",d:"Union scale rate exclusivo de collective bargaining agreement"},correct:"b",explanation:"Prevailing wage es la tasa horaria (wage + benefits) determinada por el Director of Industrial Relations para cada craft/locality. Debe pagarse en public works projects. Publicada en DIR website.",reference:"Labor Code \xA71771"},{id:"law-130",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFEn public works, debe el contratista estar registered con DIR?",options:{a:"No, solo la licencia CSLB es suficiente para operar",b:"S\xED, prime y subs deben registrarse con DIR previo al bid",c:"\xDAnicamente el GC debe estar registered con DIR estatal",d:"Solo para proyectos p\xFAblicos mayores a $1M con union labor"},correct:"b",explanation:"Desde 2015, TODOS los contratistas (prime y subs) que trabajan en public works deben estar registered con DIR y renovar anualmente. Sin registro no pueden bid ni trabajar. Aplica incluso a peque\xF1os proyectos.",reference:"Labor Code \xA71725.5"},{id:"law-131",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFCu\xE1l es el fee anual de registro con DIR para public works (aprox)?",options:{a:"Aproximadamente $400 anuales, renovado cada 1 de julio",b:"$1,000 anuales, escalonado seg\xFAn tipo de contratista CSLB",c:"$5,000 anuales, aplicable solo a contratistas con ingresos",d:"Gratuito para contratistas CSLB activos sin disciplina previa"},correct:"a",explanation:"El DIR registration fee es aproximadamente $400 anual (sujeto a cambio). Se renueva cada 1 de julio. Sin registro valido al momento de bid o trabajo, es violacion con penalties.",reference:"Labor Code \xA71725.5"},{id:"law-132",category:"Obras P\xFAblicas",difficulty:"medium",question:"En public works, \xBFqu\xE9 debe someter el contratista semanalmente?",options:{a:"Certified Payroll Records (CPR) al DIR v\xEDa eCPR online",b:"\xDAnicamente payroll interno sin certificaci\xF3n ni reporte a DIR",c:"Tax returns trimestrales al Franchise Tax Board California",d:"Bond statements certificados por el surety carrier asegurador"},correct:"a",explanation:"Certified Payroll Records (CPRs) deben someterse semanalmente a DIR electronicamente (eCPR system). Incluyen wages, hours, trades, benefits. Bajo pena de perjurio. Contratista mantiene copias por 3 a\xF1os.",reference:"Labor Code \xA71776"},{id:"law-133",category:"Obras P\xFAblicas",difficulty:"hard",question:"\xBFQue son 'apprenticeship requirements' en public works de California?",options:{a:"No existen requirements de apprentices en obra p\xFAblica CA",b:"Requiere request de apprentices y training fund contributions",c:"Aplican \xFAnicamente a proyectos construcci\xF3n del state capitol",d:"Solo a contratistas signatarios de collective bargaining union"},correct:"b",explanation:"En public works >$30,000, contratistas deben presentar DAS-140 request de apprentices al local committee y pagar training fund contributions. Deben emplear apprentices en ratio 1:5 (apprentice:journeyman) si approved.",reference:"Labor Code \xA71777.5"},{id:"law-134",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFQu\xE9 es 'retention' en public works contracts?",options:{a:"Bond surety adicional sobre el performance bond est\xE1ndar",b:"Porcentaje retenido (usualmente 5%) de cada progress payment",c:"Penalty impuesto por delay en completion por parte del GC",d:"Fee administrativo cobrado por el public entity al sub listed"},correct:"b",explanation:"Retention es un porcentaje (usualmente 5% en CA public works, puede ser menos) retenido de cada progress payment hasta el final del proyecto. Protege al owner. Libera al completion minus punch list.",reference:"Public Contract Code \xA77107"},{id:"law-135",category:"Obras P\xFAblicas",difficulty:"hard",question:"\xBFCu\xE1l es la cantidad m\xE1xima de retention permitida en public works de California?",options:{a:"10% del contrato total, est\xE1ndar anterior al a\xF1o 2012",b:"5% desde el statute 2012, tope en Public Contract \xA77201",c:"20%, aplicable a proyectos de riesgo elevado federal",d:"Sin l\xEDmite estatutario, sujeto a negociaci\xF3n entre partes"},correct:"b",explanation:"Public Contract Code \xA77201 limita retention en public works a 5% m\xE1ximo (en la mayoria de proyectos). Existen algunas excepciones pero el standard es 5%. Parte del esfuerzo de proteger cash flow de contratistas.",reference:"Public Contract Code \xA77201"},{id:"law-136",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFCuando debe el public entity liberar retention despu\xE9s de completion?",options:{a:"Cuando la awarding agency determine oportuno sin plazo fijo",b:"Dentro de 60 d\xEDas de completion; tarde incurre interest",c:"Al cumplirse un a\xF1o de terminado el proyecto sin defects",d:"Cuando el contratista lo solicite formalmente por escrito"},correct:"b",explanation:"Public Contract Code \xA77107 requiere liberacion de retention dentro de 60 d\xEDas de completion. Disputed amounts puede retenerse solo hasta 150% del disputed amount. Late release incurre 2% per month interest + attorney's fees.",reference:"Public Contract Code \xA77107"},{id:"law-137",category:"Obras P\xFAblicas",difficulty:"medium",question:"En public works, \xBFcontratistas extranjeros (out-of-state) pueden bidder?",options:{a:"No, public works CA est\xE1 reservado a contratistas CA solo",b:"S\xED, con licencia CSLB, DIR reg y prevailing wage vigente",c:"Solo en infraestructura federal o militar en territorio CA",d:"\xDAnicamente via joint venture con contratista CA licenciado"},correct:"b",explanation:"Contratistas out-of-state pueden bid CA public works si tienen licencia CSLB valida, estan DIR-registered, cumplen prevailing wage y todas las reglas. CA license es requerida para trabajar aqui.",reference:"Public Contract Code / B&P \xA77028"},{id:"law-138",category:"Obras P\xFAblicas",difficulty:"medium",question:"En public works, \xBFes obligatorio el uso de union labor?",options:{a:"S\xED, siempre, union labor es mandatorio en public works CA",b:"No por ley general; los PLAs pueden requerirlo contractualmente",c:"\xDAnicamente en state projects, no en local o regional works",d:"Solo en proyectos federales bajo Davis-Bacon Act wages"},correct:"b",explanation:"Public works en California es 'open shop' por ley \u2014 no se requiere union labor. PERO si el public entity adopta un Project Labor Agreement (PLA), el proyecto ser\xE1 union. SB 954 permite PLAs en state.",reference:"Public Contract Code / PLA statutes"},{id:"law-139",category:"Obras P\xFAblicas",difficulty:"hard",question:"\xBFQu\xE9 es el 'Subcontractor Listing Law' en California?",options:{a:"No existe statute espec\xEDfico de subcontractor listing",b:"Prime lista todo sub que har\xE1 \u22650.5% del contrato en bid",c:"Se listan solo subs con portions del contrato sobre $100,000",d:"Los subs son disclosed solamente despu\xE9s del award final"},correct:"b",explanation:"El Subletting and Subcontracting Fair Practices Act requiere que el GC en public works liste en su bid todo subcontratista que realizar\xE1 0.5% o m\xE1s del contrato. Previene 'bid shopping' despu\xE9s del award.",reference:"Public Contract Code \xA74104"},{id:"law-140",category:"Obras P\xFAblicas",difficulty:"hard",question:"Bajo el Subcontractor Listing Law, \xBFpuede el GC cambiar subs despu\xE9s del award?",options:{a:"S\xED, libremente; el GC controla la selecci\xF3n de subs post-award",b:"Requiere consent del public entity y razones espec\xEDficas listadas",c:"Solo si el sub listado accede voluntariamente por escrito firmado",d:"\xDAnicamente durante los primeros 30 d\xEDas tras adjudicaci\xF3n formal"},correct:"b",explanation:"Substitution de subs listados requiere consent del awarding body y solo por razones enumeradas: bankruptcy, failure to execute subcontract, non-performance, no license, etc. Protege a subs contra bid shopping.",reference:"Public Contract Code \xA74107"},{id:"law-141",category:"Obras P\xFAblicas",difficulty:"easy",question:"\xBFA qu\xE9 se refiere 'public works' en el contexto CSLB/DIR?",options:{a:"Solamente obras construidas directamente por agencias estatales",b:"Construcci\xF3n, alteraci\xF3n, demolition, repair con fondos p\xFAblicos",c:"\xDAnicamente proyectos de carreteras, puentes y transportaci\xF3n",d:"Cualquier proyecto de construcci\xF3n grande, sin importar funding"},correct:"b",explanation:"Public works incluye construccion, alteracion, instalacion, demolition, repair de estructuras pagada con fondos publicos (state, local, special district). Incluye hospitales publicos, escuelas, edificios federales no-militares (algunos).",reference:"Labor Code \xA71720"},{id:"law-142",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFQu\xE9 significa 'Davis-Bacon Act' (federal)?",options:{a:"Regulaci\xF3n estatal de California aplicable a labor standards",b:"Ley federal prevailing wage en federal public works >$2,000",c:"Federal minimum wage law bajo Fair Labor Standards Act",d:"National Labor Relations Act sobre organizaci\xF3n sindical"},correct:"b",explanation:"Davis-Bacon Act (1931) federal requiere prevailing wage en federally-funded construction >$2,000. Similar a CA prevailing wage pero federal. Cuando se mezcla funding, generalmente aplica la tasa m\xE1s alta.",reference:"40 U.S.C. \xA73141-3148"},{id:"law-143",category:"Obras P\xFAblicas",difficulty:"hard",question:"\xBFCual es la penalty por incumplir prevailing wage en California?",options:{a:"Solo devolver la diferencia entre wage pagado y el prevailing",b:"Back wages, penalties hasta $200/d\xEDa por worker, debarment",c:"Multa administrativa fija de $100 impuesta por Labor Commissioner",d:"Warning \xFAnicamente, sin monetary penalty en primera violaci\xF3n"},correct:"b",explanation:"Penalties por PW violations incluyen back wages, penalties de $25-$200/d\xEDa por trabajador, interes, y posible debarment (no poder bid public works) por 1-3 a\xF1os en casos severos o willful. Labor Commissioner enforces.",reference:"Labor Code \xA71775"},{id:"law-144",category:"Obras P\xFAblicas",difficulty:"easy",question:"\xBFEn public works, qui\xE9n determina los prevailing wage rates por craft y locality?",options:{a:"Cada awarding body local, seg\xFAn presupuesto del proyecto espec\xEDfico",b:"Director del Department of Industrial Relations (DIR) California",c:"Federal Department of Labor, bajo Davis-Bacon Act nacional",d:"Unions v\xEDa collective bargaining agreements publicados locales"},correct:"b",explanation:"El Director of DIR determina y publica prevailing wage rates para cada craft en cada locality, basado en surveys y collective bargaining agreements. Actualizado periodicamente. Lista oficial en DIR website.",reference:"Labor Code \xA71773"},{id:"law-145",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFEn public works, hay requisitos de 'small business' preferences?",options:{a:"No existen preferencias; solo aplica lowest responsible bidder",b:"S\xED, California tiene SBE (5%) y DVBE (3%) en state contracts",c:"Solo a nivel federal v\xEDa Small Business Administration 8(a)",d:"\xDAnicamente en condados de LA y SF con programas MBE/WBE"},correct:"b",explanation:"California state contracts tienen SBE preference (5%) y DVBE participation goal (3%). Algunas agencias locales tienen MBE/WBE/LBE programs tambien. Requiere certification. Federal tiene SBA 8(a), HUBZone, etc.",reference:"Gov Code \xA714835 et seq. / MVC \xA7999.2"},{id:"law-146",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFQu\xE9 es un 'stop payment notice' en public works?",options:{a:"Mechanic's lien equivalente aplicable a propiedad p\xFAblica",b:"Notice a public entity para retener fondos del prime unpaid",c:"Tipo de surety bond requerido en proyectos federales Miller",d:"Formal cancellation del contrato por parte del public entity"},correct:"b",explanation:"Como propiedad publica no se puede lienar, subs/suppliers unpaid pueden servir stop payment notice al public entity, obligandolo a retener fondos del prime contractor suficientes para cubrir el claim.",reference:"Civil Code \xA79350 et seq."},{id:"law-147",category:"Obras P\xFAblicas",difficulty:"hard",question:"\xBFDentro de que plazo debe servirse el stop payment notice en public works?",options:{a:"30 d\xEDas fijos desde fecha de inicio del trabajo en proyecto",b:"Antes del final payment; plazos dependen del Notice of Completion",c:"Dentro de 5 d\xEDas del primer d\xEDa de trabajo en el proyecto p\xFAblico",d:"En cualquier momento sin deadline espec\xEDfico bajo Civil Code"},correct:"b",explanation:"Stop payment notice debe servirse antes del final payment. Con Notice of Completion, 30 d\xEDas; sin, 90 d\xEDas del completion. Prime contractors deben dar preliminary notice en public works tambien en algunos casos.",reference:"Civil Code \xA79356"},{id:"law-148",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFQu\xE9 es 'liquidated damages' t\xEDpico en public works por delay?",options:{a:"No aplica LD en public works, solo damages actuales probados",b:"Monto fijo por d\xEDa de delay, ej. $500-$5,000/d\xEDa seg\xFAn contrato",c:"100% del valor del contrato como penalty m\xE1xima por delay",d:"Sin l\xEDmite estatutario; fijado caso por caso sin constraints"},correct:"b",explanation:"Public works contracts tipicamente incluyen LD por delay (comunmente $500-$5,000/d\xEDa para proyectos medianos, m\xE1s en highway/transit). Deben ser razonable estimate, no penalty. Aplican si substantial completion es tarde.",reference:"Public Contract Code / Contract-specific"},{id:"law-149",category:"Obras P\xFAblicas",difficulty:"hard",question:"\xBFQue agencia investiga fraudes en public works/prevailing wage?",options:{a:"CSLB \xFAnicamente, a trav\xE9s de su Enforcement Division central",b:"DLSE bajo DIR, y el Labor Commissioner en enforcement",c:"FBI, por tratarse de fondos p\xFAblicos federales involucrados",d:"District Attorney local exclusivamente, v\xEDa criminal investigation"},correct:"b",explanation:"DLSE bajo DIR investiga prevailing wage violations, misclassification, underpayment. El Labor Commissioner enforces. En casos criminales, el DA tambi\xE9n puede intervenir. CSLB disciplina licencia pero DLSE enforces wage laws.",reference:"Labor Code \xA779 / \xA71771"},{id:"law-150",category:"Obras P\xFAblicas",difficulty:"medium",question:"\xBFSi ganas un public works contract pero luego descubres que subestimaste, puedes withdraw tu bid?",options:{a:"S\xED, libremente, dentro de 72 horas del award por error econ\xF3mico",b:"Solo por clerical mistake, prompt notice y sin gross negligence",c:"Nunca; el bid es irrevocable una vez opened por el awarding body",d:"\xDAnicamente pagando forfeit del bid bond al public entity awarding"},correct:"b",explanation:"Bid withdraw en public works es limitado. Public Contract Code \xA75100 permite withdraw solo por clerical error (no judgmental), con notice within 5 d\xEDas, y sin gross negligence. De otra forma, pierdes bid bond o enfrentas damages.",reference:"Public Contract Code \xA75100 et seq."}];
